export default [
{
id: 'pl01', group: 'phaply', level: 1, minutes: 7,
title: 'Sổ đỏ, sổ hồng và Giấy chứng nhận theo Luật Đất đai 2024',
intro: 'Khách nào cũng hỏi "nhà này có sổ chưa, sổ gì?". Sale đọc đúng tên giấy, đúng loại đất ngay từ cuộc gọi đầu thì khách tin, và mình cũng tránh được những căn có pháp lý "lửng".',
sections: [
{ h: 'Một tên gọi chính thức cho mọi loại "sổ"', p: 'Dân gian gọi sổ đỏ (đất), sổ hồng (nhà và đất), nhưng Luật Đất đai 2024 chỉ dùng một tên: Giấy chứng nhận quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất, cấp theo mẫu thống nhất cả nước. Mẫu đang dùng hiện nay là một tờ hai trang, có mã QR để tra thông tin. Khi khách ở Long Biên cầm sổ đỏ bìa cũ cấp năm 2005, anh/chị yên tâm nói với khách: sổ cũ vẫn có giá trị, không bắt buộc đổi sang mẫu mới, chỉ đổi khi chủ nhà muốn.' },
{ h: 'Các loại đất sale phải đọc ra được', p: 'Luật chia đất thành ba nhóm lớn: nông nghiệp, phi nông nghiệp và chưa sử dụng. Trong nhóm phi nông nghiệp, sale gặp nhiều nhất là đất ở (đất ở đô thị, đất ở nông thôn) và đất thương mại, dịch vụ (nền của condotel, officetel). Đất trồng cây lâu năm, đất trồng lúa, đất nuôi trồng thủy sản thuộc nhóm nông nghiệp, không được xây nhà ở nếu chưa chuyển mục đích. Trên sổ, hãy nhìn dòng "Mục đích sử dụng" và diện tích từng loại, không chỉ nhìn tổng diện tích.' },
{ h: 'Loại đất xác định theo giấy tờ, không theo hiện trạng', p: 'Loại đất được xác định căn cứ vào Giấy chứng nhận; nếu chưa có thì căn cứ giấy tờ về quyền sử dụng đất hoặc quyết định giao đất, cho thuê, cho phép chuyển mục đích. Ví dụ ở Gia Lâm, một mảnh đã xây nhà cấp 4 nhưng sổ ghi 100 m² đất trồng cây lâu năm thì về pháp lý vẫn là đất nông nghiệp, không phải "thổ cư". Ghi nhầm loại đất trong tin đăng là lỗi dễ bị khách khiếu nại nhất.' },
{ h: 'Sổ chỉ được cấp khi xong nghĩa vụ tài chính', p: 'Giấy chứng nhận chỉ được cấp sau khi người sử dụng đất nộp xong tiền sử dụng đất, thuế, phí theo quy định, trừ trường hợp được miễn hoặc được ghi nợ. Vì vậy câu "đang chờ ra sổ" cần hỏi thêm: đã nộp xong nghĩa vụ tài chính chưa, hồ sơ nộp ở đâu, có giấy hẹn không.' },
{ h: 'Sale cần theo dõi ba luật sửa đổi', p: 'Sáng 21/11/2026, Quốc hội đã thông qua cùng lúc Luật Đất đai (sửa đổi), Luật Nhà ở (sửa đổi) và Luật Kinh doanh bất động sản (sửa đổi). Luật Đất đai và Luật Kinh doanh BĐS sửa đổi có hiệu lực từ 01/07/2027 (Luật Đất đai có vài mốc riêng: quy định công chứng từ 01/01/2027, quy định giá đất từ 01/01/2028); Luật Nhà ở sửa đổi xem ngày hiệu lực khi văn bản được công bố. Trước ngày đó áp dụng quy định hiện hành: Luật Đất đai 31/2024/QH15, Nghị quyết 254/2025/QH15, Luật Nhà ở 27/2023/QH15, Luật Kinh doanh BĐS 29/2023/QH15. Từ nay đến giữa năm 2027, sale nên theo dõi số hiệu, nghị định hướng dẫn và quy định chuyển tiếp, nhất là với hợp đồng ký trước nhưng thực hiện sau 01/07/2027. Khi khách hỏi "luật mới thế nào", hãy nói rõ cái gì đang áp dụng và cái gì chỉ áp dụng từ 01/07/2027.' },
],
exercise: 'Lấy 3 căn đang chào bán trong giỏ hàng, chụp trang 1–2 của Giấy chứng nhận (che số seri). Với mỗi căn ghi ra: tên chủ, diện tích từng loại đất, mục đích sử dụng, thời hạn sử dụng. So với tin đăng của mình và sửa ngay chỗ nào ghi sai "thổ cư".',
takeaways: [
'Sổ đỏ, sổ hồng chỉ là tên gọi dân gian; tên chính thức là Giấy chứng nhận quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất.',
'Sổ cũ cấp trước 01/08/2024 vẫn có giá trị, không bắt buộc đổi sang mẫu mới.',
'Loại đất đọc trên giấy tờ, không đọc theo hiện trạng nhà đã xây.',
'Luật Đất đai, Luật Nhà ở, Luật Kinh doanh BĐS (sửa đổi) thông qua 21/11/2026; Đất đai và Kinh doanh BĐS hiệu lực 01/07/2027; trước khi luật mới có hiệu lực, dùng luật hiện hành.',
],
refs: [
{ t: 'Luật Đất đai 2024 (số 31/2024/QH15), Điều 9 – Phân loại đất' },
{ t: 'Luật Đất đai 2024 (số 31/2024/QH15), Điều 10 – Xác định loại đất' },
{ t: 'Luật Đất đai 2024 (số 31/2024/QH15), Điều 134, Điều 135 khoản 3 – Giấy chứng nhận và nguyên tắc cấp' },
{ t: 'Luật Đất đai 2024 (số 31/2024/QH15), Điều 256 khoản 3 – Giấy chứng nhận đã cấp vẫn có giá trị' },
],
quiz: [
{ q: 'Khách cầm sổ đỏ bìa cũ cấp năm 2005 và hỏi có phải đổi sang mẫu mới mới bán được không. Sale trả lời thế nào cho đúng?', options: ['Phải đổi sang mẫu mới trước khi công chứng', 'Chỉ phải đổi nếu sổ cấp trước năm 2009', 'Sổ cũ vẫn có giá trị, không bắt buộc đổi; muốn thì làm thủ tục cấp đổi', 'Sổ cũ chỉ còn giá trị đến hết năm 2026'], answer: 2, why: 'Giấy chứng nhận đã cấp trước khi Luật Đất đai 2024 có hiệu lực vẫn có giá trị pháp lý và không phải cấp đổi; chủ sở hữu có nhu cầu thì được cấp đổi. Không có mốc "trước 2009" hay "hết 2026".', ref: 'Điều 256 khoản 3 Luật Đất đai 2024' },
{ q: 'Theo Luật Đất đai 2024, đất đai được chia thành mấy nhóm lớn?', options: ['Hai nhóm: thổ cư và nông nghiệp', 'Ba nhóm: nông nghiệp, phi nông nghiệp, chưa sử dụng', 'Bốn nhóm: đất ở, đất nông nghiệp, đất rừng, đất công', 'Năm nhóm theo mục đích kinh tế'], answer: 1, why: 'Luật chia đất thành nhóm đất nông nghiệp, nhóm đất phi nông nghiệp và nhóm đất chưa sử dụng. "Thổ cư" chỉ là cách nói quen của đất ở, thuộc nhóm phi nông nghiệp.', ref: 'Điều 9 Luật Đất đai 2024' },
{ q: 'Một mảnh ở Gia Lâm đã có nhà cấp 4, nhưng sổ ghi toàn bộ là đất trồng cây lâu năm. Về pháp lý, đây là đất gì?', options: ['Đất ở, vì đã có nhà ở ổn định', 'Đất ở nông thôn, vì nằm ở xã', 'Đất phi nông nghiệp khác', 'Đất nông nghiệp, vì loại đất xác định theo Giấy chứng nhận'], answer: 3, why: 'Loại đất được xác định căn cứ Giấy chứng nhận đã cấp. Nhà xây trên đất trồng cây lâu năm không làm mảnh đất thành đất ở; muốn thành đất ở phải được phép chuyển mục đích.', ref: 'Điều 10 Luật Đất đai 2024' },
{ q: 'Condotel, officetel thường nằm trên loại đất nào?', options: ['Đất thương mại, dịch vụ', 'Đất ở đô thị', 'Đất xây dựng trụ sở cơ quan', 'Đất sử dụng vào mục đích công cộng'], answer: 0, why: 'Đất thương mại, dịch vụ thuộc nhóm đất sản xuất, kinh doanh phi nông nghiệp. Đây là điểm khác cốt lõi với căn hộ chung cư để ở trên đất ở.', ref: 'Điều 9 khoản 3 Luật Đất đai 2024' },
{ q: 'Chủ nhà nói "sổ đang chờ ra". Câu hỏi nào giúp sale đánh giá đúng nhất tiến độ?', options: ['Nhà mình đã xây bao nhiêu năm rồi ạ?', 'Anh/chị đã nộp xong tiền sử dụng đất, thuế phí chưa và có giấy hẹn trả kết quả không ạ?', 'Hàng xóm xung quanh có sổ hết chưa ạ?', 'Anh/chị có muốn bán nhanh không ạ?'], answer: 1, why: 'Giấy chứng nhận chỉ được cấp sau khi hoàn thành nghĩa vụ tài chính (trừ trường hợp miễn, ghi nợ). Giấy hẹn và biên lai nộp tiền là bằng chứng hồ sơ đang thật sự được xử lý.', ref: 'Điều 135 khoản 3 Luật Đất đai 2024' },
{ q: 'Tháng 11/2026, khách hỏi luật đất đai mới đã áp dụng chưa. Thông tin nào đúng?', options: ['Luật Đất đai (sửa đổi) đã áp dụng từ 01/01/2026', 'Luật Đất đai 2024 đã hết hiệu lực', 'Luật Đất đai (sửa đổi) đã thông qua ngày 21/11/2026, hiệu lực từ 01/07/2027; hiện vẫn dùng luật 2024 và Nghị quyết 254/2025/QH15', 'Chưa có luật sửa đổi nào được thông qua'], answer: 2, why: 'Ngày 21/11/2026 Quốc hội thông qua Luật Đất đai (sửa đổi), hiệu lực 01/07/2027, cùng Luật Nhà ở (sửa đổi) và Luật Kinh doanh BĐS (sửa đổi). Từ 01/01/2026 có Nghị quyết 254/2025/QH15 tháo gỡ một số vướng mắc, áp dụng song song với Luật Đất đai 2024.' },
],
},
{
id: 'pl02', group: 'phaply', level: 1, minutes: 7,
title: 'Năm điều kiện để nhà đất được phép mua bán',
intro: 'Một giao dịch đổ vỡ ở phòng công chứng làm mất cả khách lẫn uy tín. Năm điều kiện trong Luật Đất đai và điều kiện nhà ở tham gia giao dịch là checklist sale phải kiểm trước khi nhận cọc.',
sections: [
{ h: 'Năm điều kiện chung khi chuyển nhượng đất', p: 'Người sử dụng đất chỉ được chuyển nhượng, tặng cho, thế chấp khi: (1) có Giấy chứng nhận (trừ vài trường hợp như thừa kế); (2) đất không có tranh chấp hoặc tranh chấp đã được giải quyết xong; (3) quyền sử dụng đất không bị kê biên để bảo đảm thi hành án; (4) còn trong thời hạn sử dụng đất; (5) không bị áp dụng biện pháp khẩn cấp tạm thời. Thiếu một trong năm điều kiện, phòng công chứng sẽ từ chối.' },
{ h: 'Điều kiện riêng với nhà ở', p: 'Luật Nhà ở 2023 yêu cầu nhà tham gia mua bán phải có Giấy chứng nhận (trừ nhà hình thành trong tương lai), không có tranh chấp, khiếu kiện về quyền sở hữu, không bị kê biên, còn thời hạn sở hữu nếu sở hữu có thời hạn, và không thuộc diện đã có quyết định thu hồi đất, thông báo giải tỏa, phá dỡ. Ví dụ nhà mặt ngõ ở Hoàng Mai nằm trong chỉ giới mở đường đã có thông báo thu hồi thì không nên nhận cọc dù chủ nhà có sổ.' },
{ h: 'Những thứ sale kiểm được ngay', p: 'Xem bản gốc Giấy chứng nhận và trang bổ sung (thế chấp, biến động). Hỏi chủ nhà có đang thế chấp ngân hàng không; nếu có, việc bán cần ngân hàng đồng ý và thường phải tất toán hoặc giải chấp. Đề nghị chủ nhà cùng đi tra cứu thông tin thửa đất tại cơ quan đăng ký đất đai, hỏi tổ dân phố về tranh chấp ranh giới. Ghi lại kết quả kiểm tra vào phiếu nhận nhà.' },
{ h: 'Trường hợp được ghi nợ tiền sử dụng đất', p: 'Nếu sổ ghi "nợ tiền sử dụng đất" hoặc chủ đang được chậm nộp nghĩa vụ tài chính, chủ phải nộp xong khoản nợ trước khi chuyển nhượng. Sale nên báo khách và chủ nhà từ đầu để tính vào dòng tiền, tránh đến ngày ký mới phát hiện.' },
],
exercise: 'Soạn một phiếu kiểm tra pháp lý 1 trang gồm 5 điều kiện của Luật Đất đai và điều kiện "không có quyết định thu hồi" của Luật Nhà ở. Dùng phiếu này cho căn kế tiếp anh/chị nhận bán, đánh dấu từng ô kèm nguồn kiểm tra.',
takeaways: [
'Năm điều kiện: có sổ, không tranh chấp, không kê biên, còn thời hạn, không bị biện pháp khẩn cấp tạm thời.',
'Nhà đã có quyết định thu hồi đất, thông báo giải tỏa thì không được mua bán.',
'Ghi nợ tiền sử dụng đất phải trả xong trước khi chuyển nhượng.',
'Đang thế chấp ngân hàng: cần ngân hàng đồng ý, thường phải giải chấp.',
],
refs: [
{ t: 'Luật Đất đai 2024 (số 31/2024/QH15), Điều 45 khoản 1, khoản 5 – Điều kiện thực hiện quyền chuyển nhượng' },
{ t: 'Luật Nhà ở 2023 (số 27/2023/QH15), Điều 160 – Điều kiện của nhà ở tham gia giao dịch' },
],
quiz: [
{ q: 'Điều kiện nào KHÔNG nằm trong năm điều kiện chung để chuyển nhượng quyền sử dụng đất?', options: ['Có Giấy chứng nhận', 'Đất không bị kê biên để bảo đảm thi hành án', 'Người bán phải có hộ khẩu tại địa phương có đất', 'Còn trong thời hạn sử dụng đất'], answer: 2, why: 'Năm điều kiện gồm: có Giấy chứng nhận, không tranh chấp, không bị kê biên, còn thời hạn sử dụng, không bị biện pháp khẩn cấp tạm thời. Luật không đòi người bán có hộ khẩu nơi có đất.', ref: 'Điều 45 khoản 1 Luật Đất đai 2024' },
{ q: 'Chủ nhà ở Hoàng Mai có sổ hồng, nhưng phường đã có thông báo giải tỏa để mở đường. Sale nên làm gì?', options: ['Không nhận bán căn này vì nhà thuộc diện có thông báo giải tỏa không đủ điều kiện giao dịch', 'Vẫn nhận bán vì đã có sổ hồng', 'Nhận bán nhưng giảm giá 20%', 'Chỉ cần khách đồng ý là bán được'], answer: 0, why: 'Nhà ở tham gia giao dịch không được thuộc trường hợp đã có quyết định thu hồi đất, thông báo giải tỏa, phá dỡ. Có sổ chưa đủ; sự đồng ý của khách cũng không thay thế điều kiện luật định.', ref: 'Điều 160 khoản 1 Luật Nhà ở 2023' },
{ q: 'Sổ của chủ đất ghi đang nợ tiền sử dụng đất. Muốn bán thì sao?', options: ['Người mua tự nộp sau khi sang tên là được', 'Phải nộp xong khoản nợ trước khi chuyển nhượng', 'Được bán bình thường, nợ chuyển sang người mua', 'Chỉ cần ghi chú khoản nợ trong hợp đồng'], answer: 1, why: 'Người được ghi nợ hoặc chậm nộp nghĩa vụ tài chính phải nộp xong trước khi chuyển nhượng, tặng cho, thế chấp. Các bên có thể thỏa thuận ai chi tiền, nhưng khoản nợ phải được nộp xong trước.', ref: 'Điều 45 khoản 5 Luật Đất đai 2024' },
{ q: 'Đất đang có tranh chấp ranh giới với hàng xóm, đã có bản án có hiệu lực giải quyết xong. Đất có chuyển nhượng được không?', options: ['Không, đất từng tranh chấp thì cấm bán 5 năm', 'Không, phải chờ hàng xóm ký xác nhận', 'Chỉ bán được cho người thân', 'Được, vì tranh chấp đã được giải quyết bằng bản án có hiệu lực'], answer: 3, why: 'Điều kiện là đất không có tranh chấp, hoặc tranh chấp đã được giải quyết bởi cơ quan có thẩm quyền, bản án, quyết định có hiệu lực. Không có quy định cấm bán 5 năm.', ref: 'Điều 45 khoản 1 điểm b Luật Đất đai 2024' },
{ q: 'Khách hỏi: "Nhà đang thế chấp ngân hàng thì có mua được không?" Câu trả lời thực tế nào phù hợp nhất?', options: ['Không bao giờ mua được', 'Mua được ngay, ngân hàng không liên quan', 'Mua được nếu ngân hàng đồng ý; thường phải tất toán, giải chấp trước khi công chứng sang tên', 'Chỉ cần công chứng viên đồng ý'], answer: 2, why: 'Tài sản đang thế chấp bị hạn chế định đoạt; cần sự đồng ý của bên nhận thế chấp. Cách làm phổ biến là dùng tiền mua để tất toán khoản vay, giải chấp rồi mới công chứng.' },
{ q: 'Với nhà ở hình thành trong tương lai, điều kiện nào trong Điều 160 Luật Nhà ở được miễn?', options: ['Điều kiện không tranh chấp quyền sở hữu và điều kiện còn thời hạn sở hữu', 'Điều kiện không bị kê biên', 'Điều kiện không có quyết định thu hồi đất', 'Tất cả các điều kiện đều được miễn'], answer: 0, why: 'Luật ghi rõ điều kiện tại điểm b và c (không tranh chấp về quyền sở hữu; còn thời hạn sở hữu) không áp dụng với mua bán nhà ở hình thành trong tương lai; nhà này cũng không bắt buộc có Giấy chứng nhận.', ref: 'Điều 160 khoản 1 điểm e, khoản 2 Luật Nhà ở 2023' },
],
},
{
id: 'pl03', group: 'phaply', level: 1, minutes: 7,
title: 'Công chứng hợp đồng và sang tên trong 30 ngày',
intro: 'Khách hay hỏi "mua của chủ đầu tư có phải công chứng không", "ký xong bao lâu phải sang tên". Trả lời sai một câu là khách có thể mất quyền lợi hoặc bị phạt.',
sections: [
{ h: 'Mua bán giữa hai cá nhân: bắt buộc công chứng', p: 'Hợp đồng chuyển nhượng, tặng cho, thế chấp quyền sử dụng đất và hợp đồng mua bán nhà ở giữa cá nhân với nhau phải công chứng hoặc chứng thực. Với nhà ở, hợp đồng có hiệu lực từ lúc hoàn thành công chứng, chứng thực. Ví dụ anh A bán căn tập thể ở Đống Đa cho chị B: không công chứng thì hợp đồng chưa có hiệu lực, không sang tên được.' },
{ h: 'Mua của doanh nghiệp kinh doanh BĐS: công chứng tùy các bên', p: 'Khi ít nhất một bên là doanh nghiệp kinh doanh bất động sản, hợp đồng kinh doanh BĐS được công chứng hoặc chứng thực theo yêu cầu của các bên. Vì vậy khách mua căn hộ của chủ đầu tư ở Cầu Giấy ký hợp đồng mua bán tại văn phòng chủ đầu tư là hợp lệ, không bắt buộc ra phòng công chứng.' },
{ h: 'Đăng ký biến động trong 30 ngày', p: 'Sau khi chuyển nhượng, tặng cho, người sử dụng đất phải đăng ký biến động tại cơ quan có thẩm quyền trong 30 ngày kể từ ngày có biến động. Sale nên nhắc khách mốc 30 ngày ngay sau buổi công chứng, chuẩn bị sẵn hồ sơ khai thuế, lệ phí trước bạ để nộp cùng lúc. Với thừa kế, thời hạn tính từ ngày phân chia xong di sản.' },
{ h: 'Công chứng ở đâu, chứng thực ở đâu', p: 'Công chứng thực hiện tại tổ chức hành nghề công chứng; chứng thực hợp đồng về nhà ở thực hiện tại Ủy ban nhân dân cấp xã nơi có nhà. Sau sắp xếp chính quyền 2 cấp từ 01/07/2025, việc nộp hồ sơ đăng ký biến động thường qua bộ phận một cửa hoặc chi nhánh văn phòng đăng ký đất đai; nên hỏi trước nơi tiếp nhận tại địa phương có nhà. Luật Đất đai (sửa đổi) đã thông qua ngày 21/11/2026, hiệu lực từ 01/07/2027, riêng quy định về công chứng có hiệu lực từ 01/01/2027; Luật Nhà ở (sửa đổi) cũng đã thông qua cùng ngày. Trước khi luật mới có hiệu lực, áp dụng quy định hiện hành.' },
],
exercise: 'Viết sẵn một tin nhắn mẫu gửi khách sau buổi công chứng: nhắc hạn 30 ngày đăng ký biến động, danh sách giấy tờ cần mang, nơi nộp hồ sơ tại khu vực căn nhà. Lưu vào điện thoại để dùng lại.',
takeaways: [
'Cá nhân bán cho cá nhân: bắt buộc công chứng hoặc chứng thực.',
'Có một bên là doanh nghiệp kinh doanh BĐS: công chứng theo yêu cầu của các bên.',
'Đăng ký biến động trong 30 ngày kể từ ngày có biến động (chuyển nhượng, tặng cho).',
'Hợp đồng mua bán nhà ở có hiệu lực khi hoàn thành công chứng, chứng thực.',
],
refs: [
{ t: 'Luật Đất đai 2024 (số 31/2024/QH15), Điều 27 khoản 3 – Công chứng, chứng thực hợp đồng' },
{ t: 'Luật Đất đai 2024 (số 31/2024/QH15), Điều 133 khoản 3 – Thời hạn 30 ngày đăng ký biến động' },
{ t: 'Luật Nhà ở 2023 (số 27/2023/QH15), Điều 164 – Công chứng hợp đồng về nhà ở' },
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 44 khoản 4, khoản 5' },
],
quiz: [
{ q: 'Anh A (cá nhân) bán căn tập thể cho chị B (cá nhân). Hợp đồng phải thế nào?', options: ['Chỉ cần viết tay có hai bên ký', 'Phải công chứng hoặc chứng thực', 'Chỉ cần lập vi bằng', 'Chỉ cần tổ trưởng dân phố xác nhận'], answer: 1, why: 'Mua bán nhà ở, chuyển nhượng quyền sử dụng đất giữa cá nhân phải công chứng hoặc chứng thực. Vi bằng và xác nhận của tổ dân phố không thay thế được.', ref: 'Điều 164 khoản 1 Luật Nhà ở 2023' },
{ q: 'Khách mua căn hộ trực tiếp từ chủ đầu tư là doanh nghiệp kinh doanh BĐS. Hợp đồng mua bán có bắt buộc công chứng không?', options: ['Bắt buộc, nếu không thì vô hiệu', 'Bắt buộc với căn trên 3 tỷ đồng', 'Không bắt buộc; công chứng hoặc chứng thực theo yêu cầu của các bên', 'Chỉ bắt buộc khi khách vay ngân hàng'], answer: 2, why: 'Hợp đồng kinh doanh BĐS có ít nhất một bên là doanh nghiệp kinh doanh BĐS được công chứng, chứng thực theo yêu cầu của các bên. Không có ngưỡng 3 tỷ.', ref: 'Điều 44 khoản 4 Luật Kinh doanh BĐS 2023' },
{ q: 'Sau khi công chứng hợp đồng chuyển nhượng, người mua phải đăng ký biến động trong bao lâu?', options: ['10 ngày', '15 ngày', '60 ngày', '30 ngày kể từ ngày có biến động'], answer: 3, why: 'Với chuyển nhượng, tặng cho, thừa kế… người sử dụng đất phải đăng ký biến động trong 30 ngày kể từ ngày có biến động.', ref: 'Điều 133 khoản 3 Luật Đất đai 2024' },
{ q: 'Hợp đồng mua bán nhà ở giữa hai cá nhân có hiệu lực từ thời điểm nào?', options: ['Khi hoàn thành việc công chứng, chứng thực', 'Khi bên mua trả đủ tiền', 'Khi được cấp Giấy chứng nhận mới', 'Khi hai bên ký đặt cọc'], answer: 0, why: 'Với giao dịch phải công chứng, chứng thực, thời điểm có hiệu lực là thời điểm hoàn thành công chứng, chứng thực. Thanh toán hay cấp sổ là việc thực hiện hợp đồng, không phải mốc hiệu lực.', ref: 'Điều 164 khoản 1 Luật Nhà ở 2023' },
{ q: 'Hợp đồng nào dưới đây KHÔNG bắt buộc công chứng, chứng thực?', options: ['Tặng cho quyền sử dụng đất giữa hai anh em', 'Thế chấp nhà ở của cá nhân', 'Thuê nhà ở', 'Chuyển nhượng đất thổ cư giữa hai cá nhân'], answer: 2, why: 'Thuê, mượn, ở nhờ, ủy quyền quản lý nhà ở không phải công chứng, chứng thực, trừ khi các bên có nhu cầu. Tặng cho, thế chấp, chuyển nhượng giữa cá nhân đều phải công chứng hoặc chứng thực.', ref: 'Điều 164 khoản 2 Luật Nhà ở 2023' },
{ q: 'Chứng thực hợp đồng về nhà ở được thực hiện tại đâu?', options: ['Văn phòng luật sư', 'Ủy ban nhân dân cấp xã nơi có nhà ở', 'Văn phòng thừa hành viên', 'Sàn giao dịch bất động sản'], answer: 1, why: 'Công chứng làm tại tổ chức hành nghề công chứng, còn chứng thực hợp đồng về nhà ở làm tại Ủy ban nhân dân cấp xã nơi có nhà.', ref: 'Điều 164 khoản 4 Luật Nhà ở 2023' },
],
},
{
id: 'pl04', group: 'phaply', level: 1, minutes: 6,
title: 'Đặt cọc mua nhà đất: làm đúng để không mất cọc oan',
intro: 'Phần lớn tranh chấp nhà đất mà sale gặp bắt đầu từ một tờ giấy cọc sơ sài. Nắm quy tắc mất cọc, phạt cọc và giới hạn cọc với dự án giúp sale bảo vệ cả khách lẫn mình.',
sections: [
{ h: 'Quy tắc mất cọc, phạt cọc', p: 'Theo Bộ luật Dân sự, nếu bên đặt cọc từ chối giao kết hoặc thực hiện hợp đồng thì mất tiền cọc; nếu bên nhận cọc từ chối thì phải trả lại cọc và một khoản tương đương giá trị cọc, trừ khi các bên thỏa thuận khác. Ví dụ khách cọc 200 triệu (ví dụ) mua nhà ở Thanh Xuân, chủ nhà đổi ý không bán: chủ nhà phải trả 400 triệu, trừ khi giấy cọc có thỏa thuận mức khác.' },
{ h: 'Giấy cọc cần ghi những gì', p: 'Thông tin hai bên và người có chung quyền sử dụng (vợ chồng, đồng sở hữu), số Giấy chứng nhận, địa chỉ, diện tích, giá bán, số tiền cọc, hạn ký hợp đồng công chứng, ai chịu thuế phí, điều kiện hoàn cọc (ví dụ ngân hàng không duyệt vay, phát hiện quy hoạch). Nếu nhà là tài sản chung vợ chồng mà chỉ một người ký nhận cọc, rủi ro tranh chấp rất cao.' },
{ h: 'Cọc mua căn hộ của chủ đầu tư: tối đa 5%', p: 'Với nhà ở hình thành trong tương lai, chủ đầu tư chỉ được thu tiền đặt cọc không quá 5% giá bán, và chỉ khi nhà ở đã đủ điều kiện đưa vào kinh doanh; thỏa thuận cọc phải ghi rõ giá bán. Các khoản "giữ chỗ, booking" thu khi dự án chưa đủ điều kiện mở bán là vùng rủi ro, sale nên giải thích rõ cho khách đây chưa phải đặt cọc hợp lệ theo luật kinh doanh BĐS.' },
{ h: 'Nhận và giữ tiền cọc', p: 'Sale không nên tự cầm tiền cọc của khách. Tiền nên chuyển khoản thẳng vào tài khoản chủ nhà (hoặc tài khoản doanh nghiệp, với giao dịch có doanh nghiệp kinh doanh BĐS) với nội dung ghi rõ số giấy cọc. Doanh nghiệp kinh doanh BĐS và dịch vụ BĐS phải nhận tiền thanh toán qua tài khoản tại ngân hàng.' },
],
exercise: 'Lấy mẫu giấy cọc nhóm đang dùng, đối chiếu với danh sách nội dung ở mục 2. Bổ sung ít nhất 2 điều khoản còn thiếu (ví dụ điều kiện hoàn cọc khi phát hiện quy hoạch, chữ ký của vợ/chồng chủ nhà).',
takeaways: [
'Bên đặt cọc bỏ: mất cọc. Bên nhận cọc bỏ: trả cọc và một khoản tương đương, trừ khi thỏa thuận khác.',
'Chủ đầu tư chỉ được thu cọc tối đa 5% giá bán và chỉ khi nhà đã đủ điều kiện kinh doanh.',
'Tài sản chung vợ chồng: cả hai phải ký giấy cọc.',
'Tiền cọc chuyển khoản thẳng cho bên bán, sale không tự giữ.',
],
refs: [
{ t: 'Bộ luật Dân sự 2015 (số 91/2015/QH13), Điều 328 – Đặt cọc' },
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 23 khoản 5 – Cọc tối đa 5%' },
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 48 khoản 2 – Nhận tiền qua tài khoản' },
],
quiz: [
{ q: 'Khách cọc 200 triệu (ví dụ), chủ nhà đổi ý không bán. Giấy cọc không có thỏa thuận riêng. Chủ nhà phải trả khách bao nhiêu?', options: ['200 triệu', '300 triệu', '400 triệu', '1 tỷ, gấp 5 lần'], answer: 2, why: 'Bên nhận cọc từ chối thực hiện thì phải trả lại tiền cọc và một khoản tương đương giá trị cọc, tức 200 + 200 = 400 triệu, trừ khi các bên thỏa thuận khác.', ref: 'Điều 328 Bộ luật Dân sự 2015' },
{ q: 'Khách đặt cọc rồi đổi ý không mua (không có lý do được ghi trong giấy cọc). Hậu quả là gì?', options: ['Được nhận lại toàn bộ cọc', 'Mất tiền cọc cho bên bán', 'Được nhận lại một nửa', 'Phải trả thêm gấp đôi tiền cọc'], answer: 1, why: 'Bên đặt cọc từ chối giao kết hoặc thực hiện hợp đồng thì tài sản cọc thuộc về bên nhận cọc. Vì thế nên ghi rõ các điều kiện hoàn cọc ngay từ đầu.', ref: 'Điều 328 Bộ luật Dân sự 2015' },
{ q: 'Căn hộ dự án đã đủ điều kiện mở bán, giá 4 tỷ (ví dụ). Chủ đầu tư được thu tiền cọc tối đa bao nhiêu?', options: ['200 triệu (5% giá bán)', '400 triệu (10%)', '1,2 tỷ (30%)', 'Không giới hạn, tùy thỏa thuận'], answer: 0, why: 'Chủ đầu tư chỉ được thu tiền đặt cọc không quá 5% giá bán khi nhà ở đã đủ điều kiện đưa vào kinh doanh; 5% của 4 tỷ là 200 triệu.', ref: 'Điều 23 khoản 5 Luật Kinh doanh BĐS 2023' },
{ q: 'Dự án chưa có văn bản đủ điều kiện bán nhà hình thành trong tương lai, đại lý mời khách nộp "tiền đặt cọc 5%". Nhận định đúng?', options: ['Hợp lệ vì không vượt 5%', 'Hợp lệ nếu có hóa đơn', 'Hợp lệ nếu sàn bảo lãnh', 'Chưa hợp lệ, vì chủ đầu tư chỉ được thu cọc khi nhà đã đủ điều kiện kinh doanh'], answer: 3, why: 'Giới hạn 5% đi kèm điều kiện: nhà ở đã có đủ điều kiện đưa vào kinh doanh. Thu tiền sai quy định trong bán nhà hình thành trong tương lai là hành vi bị cấm.', ref: 'Điều 23 khoản 5 và Điều 8 khoản 5 Luật Kinh doanh BĐS 2023' },
{ q: 'Nhà là tài sản chung của vợ chồng chủ nhà, chỉ người chồng ký nhận cọc. Rủi ro chính là gì?', options: ['Không có rủi ro vì chồng là chủ hộ', 'Người vợ có thể không đồng ý bán, dẫn tới tranh chấp hoặc không công chứng được', 'Chỉ bị chậm sang tên vài ngày', 'Khách phải nộp thêm thuế'], answer: 1, why: 'Định đoạt tài sản chung cần sự đồng ý của cả hai vợ chồng; thiếu chữ ký người vợ thì hợp đồng chuyển nhượng khó công chứng và dễ phát sinh tranh chấp về giấy cọc.' },
{ q: 'Thỏa thuận đặt cọc mua căn hộ hình thành trong tương lai bắt buộc phải ghi rõ nội dung nào?', options: ['Giá bán, cho thuê mua căn hộ', 'Tên ngân hàng cho vay', 'Lãi suất ưu đãi', 'Tên sàn phân phối'], answer: 0, why: 'Luật yêu cầu thỏa thuận đặt cọc phải ghi rõ giá bán, cho thuê mua nhà ở, công trình xây dựng.', ref: 'Điều 23 khoản 5 Luật Kinh doanh BĐS 2023' },
],
},
{
id: 'pl05', group: 'phaply', level: 1, minutes: 7,
title: 'Hành nghề môi giới hợp pháp: chứng chỉ, nơi làm việc và hoa hồng',
intro: 'Từ khi Luật Kinh doanh BĐS 2023 có hiệu lực, môi giới "tự do" không còn hợp pháp. Bài này giúp anh/chị tự kiểm mình đã đủ điều kiện hành nghề chưa.',
sections: [
{ h: 'Hai điều kiện với cá nhân môi giới', p: 'Cá nhân hành nghề môi giới bất động sản phải có chứng chỉ hành nghề môi giới và phải hành nghề trong một doanh nghiệp kinh doanh dịch vụ sàn giao dịch BĐS hoặc một doanh nghiệp kinh doanh dịch vụ môi giới BĐS. Nghĩa là một người có chứng chỉ nhưng tự đứng ra nhận môi giới, không thuộc doanh nghiệp nào, vẫn chưa đủ điều kiện.' },
{ h: 'Chứng chỉ có hạn 5 năm', p: 'Muốn có chứng chỉ phải học khóa đào tạo kiến thức hành nghề, tốt nghiệp trung học phổ thông trở lên và thi sát hạch đạt. Chứng chỉ do UBND cấp tỉnh cấp, dùng trên cả nước trong 5 năm kể từ ngày cấp. Hết hạn thì không được tiếp tục hành nghề; muốn cấp lại phải thi phần kiến thức cơ sở. Chứng chỉ không được cho thuê, cho mượn.' },
{ h: 'Điều kiện với doanh nghiệp môi giới', p: 'Doanh nghiệp kinh doanh dịch vụ môi giới phải có quy chế hoạt động, cơ sở vật chất kỹ thuật, có tối thiểu 01 người có chứng chỉ, và gửi thông tin doanh nghiệp đến cơ quan quản lý kinh doanh BĐS cấp tỉnh để đăng lên hệ thống thông tin về nhà ở và thị trường BĐS trước khi hoạt động.' },
{ h: 'Hoa hồng nhận từ đâu, do ai thỏa thuận', p: 'Cá nhân môi giới nhận thù lao, hoa hồng từ doanh nghiệp sàn hoặc doanh nghiệp môi giới nơi mình làm việc; mức do hai bên thỏa thuận. Doanh nghiệp thu phí dịch vụ của khách theo hợp đồng. Môi giới phải cung cấp thông tin trung thực, bồi thường nếu gây thiệt hại do lỗi của mình và tham gia bồi dưỡng kiến thức hằng năm.' },
],
exercise: 'Kiểm tra chứng chỉ của mình: số chứng chỉ, ngày cấp, ngày hết hạn (cộng 5 năm). Nếu còn dưới 6 tháng, ghi lịch đăng ký thi cấp lại. Nếu chưa có, tìm lịch thi sát hạch của Hà Nội và lên kế hoạch học.',
takeaways: [
'Cá nhân môi giới cần chứng chỉ và phải làm trong doanh nghiệp sàn hoặc doanh nghiệp môi giới.',
'Chứng chỉ có giá trị 5 năm; hết hạn là không được hành nghề.',
'Doanh nghiệp môi giới cần tối thiểu 1 người có chứng chỉ.',
'Hoa hồng của cá nhân do cá nhân và doanh nghiệp thỏa thuận.',
],
refs: [
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 61 – Điều kiện kinh doanh dịch vụ môi giới' },
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 63, Điều 65 – Hoa hồng và nghĩa vụ môi giới' },
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 70 – Thi sát hạch, cấp chứng chỉ' },
{ t: 'Nghị định 96/2024/NĐ-CP (sửa đổi bởi 54/2026/NĐ-CP), Điều 31 khoản 4, Điều 32 – Thời hạn chứng chỉ' },
],
quiz: [
{ q: 'Anh Minh có chứng chỉ môi giới nhưng tự nhận bán nhà cho người quen, không làm cho doanh nghiệp nào. Anh Minh đã đủ điều kiện hành nghề chưa?', options: ['Đủ, vì có chứng chỉ', 'Đủ, nếu chỉ môi giới dưới 10 căn/năm', 'Chưa đủ, vì cá nhân phải hành nghề trong doanh nghiệp sàn hoặc doanh nghiệp môi giới', 'Đủ, nếu kê khai thuế'], answer: 2, why: 'Cá nhân hành nghề môi giới phải có chứng chỉ VÀ hành nghề trong một doanh nghiệp kinh doanh dịch vụ sàn giao dịch hoặc dịch vụ môi giới BĐS.', ref: 'Điều 61 khoản 2 Luật Kinh doanh BĐS 2023' },
{ q: 'Chứng chỉ hành nghề môi giới bất động sản có thời hạn bao lâu?', options: ['5 năm kể từ ngày cấp', '3 năm', '10 năm', 'Vô thời hạn'], answer: 0, why: 'Chứng chỉ có giá trị sử dụng trên phạm vi cả nước trong thời hạn 05 năm kể từ ngày được cấp.', ref: 'Điều 31 khoản 4 Nghị định 96/2024/NĐ-CP' },
{ q: 'Chứng chỉ của chị Lan hết hạn tháng trước. Chị muốn tiếp tục làm. Đúng quy định là gì?', options: ['Được làm tiếp 12 tháng trong lúc chờ cấp lại', 'Chỉ cần nộp đơn gia hạn, không cần thi', 'Không được hành nghề; phải đăng ký thi lại phần kiến thức cơ sở để được cấp lại', 'Được làm tiếp nếu doanh nghiệp đồng ý'], answer: 2, why: 'Người có chứng chỉ đã hết hạn không được phép tiếp tục hành nghề. Muốn cấp lại phải thi sát hạch, chỉ thi phần kiến thức cơ sở.', ref: 'Điều 32 Nghị định 96/2024/NĐ-CP' },
{ q: 'Điều kiện nào là bắt buộc để cá nhân được dự thi sát hạch cấp chứng chỉ môi giới?', options: ['Có bằng đại học chuyên ngành kinh tế', 'Có giấy chứng nhận hoàn thành khóa đào tạo kiến thức hành nghề môi giới', 'Có ít nhất 2 năm kinh nghiệm bán hàng', 'Có hộ khẩu tại tỉnh tổ chức thi'], answer: 1, why: 'Người dự thi cần có giấy chứng nhận hoàn thành khóa học, tốt nghiệp THPT trở lên và nộp hồ sơ, kinh phí dự thi. Không đòi bằng đại học hay kinh nghiệm.', ref: 'Điều 70 khoản 1 Luật Kinh doanh BĐS 2023' },
{ q: 'Doanh nghiệp kinh doanh dịch vụ môi giới BĐS phải có tối thiểu bao nhiêu người có chứng chỉ môi giới?', options: ['02 người', '05 người', 'Toàn bộ nhân viên', '01 người'], answer: 3, why: 'Doanh nghiệp môi giới phải có tối thiểu 01 cá nhân có chứng chỉ môi giới, kèm quy chế hoạt động và cơ sở vật chất kỹ thuật. Tuy vậy, từng cá nhân hành nghề vẫn phải tự có chứng chỉ.', ref: 'Điều 61 khoản 1 Luật Kinh doanh BĐS 2023' },
{ q: 'Bạn thân xin mượn chứng chỉ của anh/chị để đứng tên một giao dịch. Nên làm gì?', options: ['Cho mượn nếu là bạn thân', 'Từ chối, vì người được cấp chứng chỉ không được cho thuê, cho mượn chứng chỉ', 'Cho mượn nếu có giấy ủy quyền', 'Cho mượn nếu chia hoa hồng'], answer: 1, why: 'Người được cấp chứng chỉ không được cho thuê, cho mượn hoặc cho người khác dùng tên và chứng chỉ của mình; vi phạm có thể bị thu hồi chứng chỉ.', ref: 'Điều 31 khoản 7 Nghị định 96/2024/NĐ-CP' },
],
},
{
id: 'pl06', group: 'phaply', level: 2, minutes: 7,
title: 'Sàn giao dịch bất động sản: làm gì, có bắt buộc không',
intro: 'Nhiều sale vẫn nói "căn dự án bắt buộc bán qua sàn". Theo Luật Kinh doanh BĐS 2023 thì không phải vậy. Hiểu đúng giúp anh/chị tư vấn chính xác và nói rõ giá trị thật của sàn.',
sections: [
{ h: 'Qua sàn là khuyến khích, không phải bắt buộc', p: 'Luật Kinh doanh BĐS 2023 ghi Nhà nước khuyến khích giao dịch mua bán, chuyển nhượng, cho thuê qua sàn giao dịch. Chủ đầu tư có thể tự bán hoặc lựa chọn phân phối qua sàn; nếu chọn sàn thì phải cung cấp đầy đủ, trung thực hồ sơ cho sàn. Vì vậy câu đúng với khách là: "Căn này bán qua sàn nên sàn đã kiểm tra pháp lý", không phải "luật bắt buộc qua sàn".' },
{ h: 'Sàn phải làm những việc gì', p: 'Sàn kiểm tra tính pháp lý và điều kiện đưa vào kinh doanh của BĐS trước khi niêm yết; môi giới, hỗ trợ đàm phán; hỗ trợ ký hợp đồng, thanh toán, bàn giao; lưu trữ hồ sơ; xác nhận giao dịch qua sàn và báo cáo cơ quan quản lý cấp tỉnh. Sàn có quyền từ chối đưa lên sàn BĐS không đủ điều kiện kinh doanh và phải bồi thường nếu gây thiệt hại do lỗi của mình.' },
{ h: 'Điều kiện để một sàn hoạt động', p: 'Sàn phải là doanh nghiệp có cụm từ "sàn giao dịch bất động sản" trong tên, được cơ quan quản lý kinh doanh BĐS cấp tỉnh cấp giấy phép hoạt động, có người quản lý điều hành đã hoàn thành khóa đào tạo, có quy trình giao dịch công khai và địa điểm cố định. Khi ký với cá nhân môi giới, người đó phải đủ điều kiện hành nghề.' },
{ h: 'Dùng sàn làm lợi thế tư vấn', p: 'Khi khách lo pháp lý căn hộ tại một dự án ở Tây Hồ, sale có thể nói: "Sàn bên em đã kiểm tra văn bản đủ điều kiện bán và hồ sơ pháp lý trước khi niêm yết, anh/chị có thể yêu cầu xem". Lưu ý: Luật Kinh doanh BĐS (sửa đổi) đã thông qua ngày 21/11/2026, hiệu lực từ 01/07/2027; trước ngày đó áp dụng quy định hiện hành (Luật 29/2023/QH15).' },
],
exercise: 'Viết 3 câu giới thiệu vai trò của sàn nơi anh/chị làm việc với khách mua căn hộ dự án, chỉ dùng các việc luật giao cho sàn (kiểm tra pháp lý, hỗ trợ ký hợp đồng, xác nhận giao dịch). Bỏ hết câu nào nói "bắt buộc qua sàn".',
takeaways: [
'Luật 2023 khuyến khích, không bắt buộc giao dịch qua sàn.',
'Sàn phải kiểm tra pháp lý, điều kiện kinh doanh trước khi niêm yết.',
'Sàn cần giấy phép hoạt động do cơ quan quản lý cấp tỉnh cấp.',
'Sàn bồi thường thiệt hại do lỗi của mình gây ra cho khách.',
],
refs: [
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 7 khoản 7 – Khuyến khích giao dịch qua sàn' },
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 23 khoản 4 điểm c – Chủ đầu tư lựa chọn phân phối qua sàn' },
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 54, Điều 55, Điều 56, Điều 58 – Sàn giao dịch BĐS' },
],
quiz: [
{ q: 'Khách hỏi: "Luật bắt buộc căn hộ dự án phải bán qua sàn đúng không?" Theo Luật Kinh doanh BĐS 2023, sale trả lời thế nào?', options: ['Đúng, mọi giao dịch của chủ đầu tư phải qua sàn', 'Không bắt buộc; Nhà nước khuyến khích, chủ đầu tư có thể lựa chọn phân phối qua sàn', 'Chỉ bắt buộc với dự án trên 500 căn', 'Chỉ bắt buộc với khách nước ngoài'], answer: 1, why: 'Luật 2023 dùng từ "khuyến khích" giao dịch qua sàn, và nói chủ đầu tư cung cấp hồ sơ cho sàn "trong trường hợp lựa chọn phân phối sản phẩm thông qua sàn".', ref: 'Điều 7 khoản 7, Điều 23 khoản 4 Luật Kinh doanh BĐS 2023' },
{ q: 'Việc nào là nội dung hoạt động bắt buộc của sàn trước khi niêm yết một BĐS?', options: ['Kiểm tra tính pháp lý và điều kiện đưa vào kinh doanh', 'Cam kết giá bán lại cho khách', 'Định giá thay ngân hàng', 'Nộp thuế thay người bán'], answer: 0, why: 'Sàn kiểm tra tính pháp lý và điều kiện đưa vào kinh doanh, rồi mới niêm yết, cung cấp thông tin BĐS đủ điều kiện.', ref: 'Điều 56 khoản 1 Luật Kinh doanh BĐS 2023' },
{ q: 'Trước khi hoạt động, sàn giao dịch BĐS cần gì từ cơ quan quản lý kinh doanh BĐS cấp tỉnh?', options: ['Chỉ cần thông báo bằng email', 'Không cần gì nếu đã có đăng ký doanh nghiệp', 'Giấy xác nhận của hiệp hội', 'Giấy phép hoạt động'], answer: 3, why: 'Sàn phải gửi hồ sơ đến cơ quan quản lý kinh doanh BĐS cấp tỉnh nơi có trụ sở chính để được cấp giấy phép hoạt động.', ref: 'Điều 54 khoản 3 Luật Kinh doanh BĐS 2023' },
{ q: 'Tên doanh nghiệp kinh doanh dịch vụ sàn giao dịch BĐS phải có yếu tố nào?', options: ['Chữ "Land"', 'Tên của chủ đầu tư', 'Cụm từ "sàn giao dịch bất động sản"', 'Mã số chứng chỉ của giám đốc'], answer: 2, why: 'Tên doanh nghiệp kinh doanh dịch vụ sàn phải có cụm từ "sàn giao dịch bất động sản" và không trùng, gây nhầm lẫn với sàn khác.', ref: 'Điều 54 khoản 2 Luật Kinh doanh BĐS 2023' },
{ q: 'Sàn niêm yết sai thông tin pháp lý, khách bị thiệt hại. Trách nhiệm của sàn?', options: ['Không chịu trách nhiệm vì chỉ là trung gian', 'Chịu trách nhiệm về thông tin mình niêm yết và bồi thường thiệt hại do lỗi của mình', 'Chỉ chịu trách nhiệm nếu khách mua qua đêm', 'Chuyển toàn bộ trách nhiệm cho nhân viên môi giới'], answer: 1, why: 'Sàn phải niêm yết, cung cấp đầy đủ, trung thực hồ sơ, chịu trách nhiệm về thông tin do mình cung cấp và bồi thường thiệt hại do lỗi của mình.', ref: 'Điều 58 khoản 2, khoản 6 Luật Kinh doanh BĐS 2023' },
{ q: 'Người quản lý, điều hành sàn giao dịch BĐS phải đáp ứng điều kiện nào?', options: ['Có quyền quản lý doanh nghiệp và hoàn thành khóa đào tạo quản lý, điều hành sàn', 'Có chứng chỉ định giá', 'Có 10 năm kinh nghiệm', 'Là cổ đông lớn nhất'], answer: 0, why: 'Người quản lý, điều hành sàn phải có quyền quản lý doanh nghiệp theo Luật Doanh nghiệp và có giấy chứng nhận hoàn thành khóa học quản lý, điều hành sàn.', ref: 'Điều 55 khoản 1 Luật Kinh doanh BĐS 2023' },
],
},
{
id: 'pl07', group: 'phaply', level: 2, minutes: 8,
title: 'Nhà ở hình thành trong tương lai: khi nào được mở bán',
intro: 'Khách mua căn hộ "trên giấy" chịu rủi ro lớn nhất ở thời điểm ký hợp đồng. Sale nắm bộ điều kiện mở bán sẽ biết nên đưa khách vào giai đoạn nào và cần xin xem giấy tờ gì.',
sections: [
{ h: 'Bốn nhóm giấy tờ bắt buộc', p: 'Nhà ở hình thành trong tương lai chỉ được đưa vào kinh doanh khi: đã khởi công theo pháp luật xây dựng; có giấy tờ về quyền sử dụng đất (quyết định giao đất, cho thuê đất, cho phép chuyển mục đích hoặc Giấy chứng nhận); có giấy phép xây dựng (hoặc thông báo khởi công và hồ sơ thiết kế nếu không phải xin phép); và có giấy tờ nghiệm thu hạ tầng kỹ thuật tương ứng tiến độ. Với chung cư, tòa hỗn hợp có nhà ở phải có biên bản nghiệm thu hoàn thành phần móng.' },
{ h: 'Văn bản thông báo của Sở Xây dựng', p: 'Trước khi bán, chủ đầu tư phải gửi thông báo nhà ở đủ điều kiện bán đến cơ quan quản lý kinh doanh BĐS cấp tỉnh. Trong 15 ngày, cơ quan này kiểm tra và trả lời bằng văn bản; văn bản trả lời được đăng trên cổng thông tin về nhà ở và thị trường BĐS. Đây là giấy tờ đầu tiên sale nên xin xem khi nhận dự án.' },
{ h: 'Điều kiện đi kèm', p: 'Dự án phải được chấp thuận và có mục đích xây nhà để bán, cho thuê mua; không bị kê biên, không đang bị đình chỉ giao dịch; thông tin dự án đã được công khai theo luật. Nếu chủ đầu tư đã thế chấp dự án hoặc nhà ở thì phải giải chấp trước khi ký hợp đồng mua bán với khách (trừ một số trường hợp luật định); việc đã giải chấp được nêu trong văn bản thông báo nhà ở đủ điều kiện bán.' },
{ h: 'Ứng dụng khi tư vấn', p: 'Với một dự án mới ở Hà Đông, nếu chưa có văn bản Sở Xây dựng xác nhận đủ điều kiện bán, sale chỉ nên giới thiệu thông tin dự án, không nhận tiền cọc. Khi đã có văn bản, hãy chụp lại số văn bản, ngày ký và danh sách tòa/căn được bán để đối chiếu đúng căn khách chọn.' },
],
exercise: 'Với dự án anh/chị đang bán, tìm văn bản thông báo nhà ở hình thành trong tương lai đủ điều kiện bán của Sở Xây dựng. Ghi lại: số văn bản, ngày ký, các tòa và số căn được phép bán. Đối chiếu với căn trong giỏ hàng của mình.',
takeaways: [
'Cần: khởi công, giấy tờ đất, giấy phép xây dựng, nghiệm thu hạ tầng (chung cư: nghiệm thu móng).',
'Phải có văn bản của cơ quan quản lý cấp tỉnh xác nhận đủ điều kiện bán; trả lời trong 15 ngày.',
'Chưa có văn bản đủ điều kiện bán thì chưa nhận cọc.',
'Dự án, nhà ở đang thế chấp phải giải chấp trước khi ký hợp đồng mua bán với khách.',
],
refs: [
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 24 – Điều kiện nhà ở hình thành trong tương lai đưa vào kinh doanh' },
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 14 khoản 1 – Điều kiện chung áp dụng kèm' },
{ t: 'Nghị định 96/2024/NĐ-CP (sửa đổi bởi 54/2026/NĐ-CP), Điều 8 – Thủ tục thông báo nhà ở đủ điều kiện bán' },
{ t: 'Luật Nhà ở 2023 (số 27/2023/QH15), Điều 183 khoản 2 – Giải chấp trước khi bán nhà ở đã thế chấp' },
],
quiz: [
{ q: 'Với dự án chung cư hình thành trong tương lai, giấy tờ nghiệm thu nào là bắt buộc trước khi mở bán?', options: ['Nghiệm thu hoàn thành toàn bộ tòa nhà', 'Nghiệm thu hoàn thành xây dựng phần móng', 'Nghiệm thu cất nóc', 'Nghiệm thu phòng cháy chữa cháy'], answer: 1, why: 'Trường hợp nhà chung cư, tòa nhà hỗn hợp có nhà ở phải có giấy tờ chứng minh đã nghiệm thu hoàn thành xây dựng phần móng.', ref: 'Điều 24 khoản 3 điểm c Luật Kinh doanh BĐS 2023' },
{ q: 'Sau khi nhận thông báo của chủ đầu tư, cơ quan quản lý kinh doanh BĐS cấp tỉnh phải trả lời trong bao lâu?', options: ['15 ngày', '30 ngày', '7 ngày làm việc', '45 ngày'], answer: 0, why: 'Trong thời hạn 15 ngày kể từ ngày nhận được thông báo, cơ quan quản lý kinh doanh BĐS cấp tỉnh kiểm tra và trả lời bằng văn bản.', ref: 'Điều 24 khoản 4 Luật Kinh doanh BĐS 2023' },
{ q: 'Giấy tờ nào sau đây KHÔNG được tính là giấy tờ về quyền sử dụng đất theo Điều 24?', options: ['Quyết định giao đất', 'Quyết định cho phép chuyển mục đích sử dụng đất', 'Giấy chứng nhận quyền sử dụng đất', 'Quyết định chủ trương đầu tư'], answer: 3, why: 'Điều 24 liệt kê quyết định giao đất, cho thuê đất kèm hợp đồng thuê, quyết định cho phép chuyển mục đích và các loại Giấy chứng nhận. Chủ trương đầu tư chưa phải giấy tờ về quyền sử dụng đất.', ref: 'Điều 24 khoản 2 Luật Kinh doanh BĐS 2023' },
{ q: 'Dự án ở Hà Đông đã khởi công nhưng chưa có văn bản của Sở Xây dựng về nhà ở đủ điều kiện bán. Sale nên làm gì?', options: ['Nhận cọc 5% để giữ căn đẹp', 'Ký hợp đồng mua bán trước, bổ sung văn bản sau', 'Chỉ giới thiệu thông tin, chưa nhận tiền cọc hay ký hợp đồng', 'Cho khách ký hợp đồng góp vốn thay thế'], answer: 2, why: 'Hợp đồng kinh doanh BĐS chỉ được ký khi BĐS đủ điều kiện đưa vào kinh doanh; tiền cọc chỉ được thu khi nhà đã đủ điều kiện. Văn bản thông báo của cơ quan cấp tỉnh là bước bắt buộc trước khi bán.', ref: 'Điều 24 khoản 4, Điều 44 khoản 3 Luật Kinh doanh BĐS 2023' },
{ q: 'Văn bản trả lời của Sở Xây dựng về nhà ở đủ điều kiện bán được công khai ở đâu?', options: ['Chỉ gửi riêng cho chủ đầu tư', 'Đăng trên cổng thông tin về nhà ở và thị trường bất động sản', 'Dán tại nhà văn hóa tổ dân phố', 'Đăng trên báo in hằng ngày'], answer: 1, why: 'Nghị định 96 yêu cầu cơ quan quản lý cấp tỉnh trả lời bằng văn bản và đăng tải văn bản trả lời trên cổng thông tin về nhà ở và thị trường BĐS.', ref: 'Điều 8 khoản 4 Nghị định 96/2024/NĐ-CP' },
{ q: 'Nhà ở hình thành trong tương lai có cần được công khai thông tin trước khi kinh doanh không?', options: ['Có, phải công khai thông tin BĐS, dự án theo luật', 'Không, chỉ công khai sau khi bàn giao', 'Chỉ công khai nếu bán qua sàn', 'Chỉ công khai giá, không cần pháp lý'], answer: 0, why: 'Một trong các điều kiện là đã được công khai thông tin về BĐS, dự án BĐS đưa vào kinh doanh theo Điều 6 của luật.', ref: 'Điều 24 khoản 7 Luật Kinh doanh BĐS 2023' },
],
},
{
id: 'pl08', group: 'phaply', level: 2, minutes: 7,
title: 'Tiến độ thanh toán nhà hình thành trong tương lai: mốc 30 – 70 – 95',
intro: 'Khách so sánh chính sách thanh toán giữa các dự án rất kỹ. Sale cần biết luật cho phép chủ đầu tư thu tối đa bao nhiêu ở mỗi mốc để giải thích và phát hiện chính sách bất thường.',
sections: [
{ h: 'Lần đầu tối đa 30%, đã gồm cọc', p: 'Thanh toán khi mua nhà ở hình thành trong tương lai được chia nhiều lần; lần đầu không quá 30% giá trị hợp đồng, bao gồm cả tiền đặt cọc. Ví dụ căn 5 tỷ (ví dụ), khách đã cọc 250 triệu (5%) thì đợt ký hợp đồng tối đa thêm 1,25 tỷ để tổng lần đầu không vượt 1,5 tỷ.' },
{ h: 'Trước bàn giao tối đa 70%', p: 'Các lần tiếp theo phải phù hợp tiến độ xây dựng, và tổng số tiền thu khi chưa bàn giao nhà không quá 70% giá trị hợp đồng. Nếu bên bán là tổ chức kinh tế có vốn đầu tư nước ngoài thuộc diện luật quy định thì mức trần là 50%. Với thuê mua, tổng tiền trả trước không quá 50% giá trị hợp đồng thuê mua.' },
{ h: 'Chưa có sổ thì tối đa 95%', p: 'Khi bên mua chưa được cấp Giấy chứng nhận, bên bán không được thu quá 95% giá trị hợp đồng; 5% còn lại thu khi cơ quan nhà nước đã cấp sổ cho bên mua. Chủ đầu tư phải nộp hồ sơ đề nghị cấp sổ cho người mua trong 50 ngày kể từ ngày bàn giao nhà, trừ khi người mua tự nguyện tự làm.' },
{ h: 'Thanh toán qua tài khoản và luật sắp thay đổi', p: 'Chủ đầu tư nhận tiền của khách qua tài khoản mở tại tổ chức tín dụng. Khi khách đề nghị "chuyển tiền mặt cho nhân viên", sale phải từ chối. Luật Kinh doanh BĐS (sửa đổi) đã thông qua ngày 21/11/2026, hiệu lực từ 01/07/2027; trước ngày đó áp dụng quy định hiện hành. Khi luật mới có số hiệu và văn bản hướng dẫn, cần đọc lại các mốc thanh toán trước khi tư vấn cho hợp đồng ký sau 01/07/2027.' },
],
exercise: 'Lấy chính sách thanh toán của dự án anh/chị đang bán, lập bảng các đợt thanh toán và cộng dồn phần trăm. Đánh dấu ba mốc: lần đầu (≤30%), trước bàn giao (≤70%), trước khi có sổ (≤95%). Nếu có đợt nào vượt, hỏi lại quản lý dự án trước khi gửi khách.',
takeaways: [
'Lần đầu không quá 30% giá trị hợp đồng, đã gồm tiền cọc.',
'Trước khi bàn giao không quá 70% (bên bán FDI thuộc diện luật định: 50%).',
'Chưa cấp sổ thì không thu quá 95%.',
'Chủ đầu tư nộp hồ sơ cấp sổ cho người mua trong 50 ngày từ ngày bàn giao.',
],
refs: [
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 25 – Thanh toán mua bán, thuê mua nhà ở hình thành trong tương lai' },
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 17 khoản 3 – Hạn 50 ngày nộp hồ sơ cấp sổ' },
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 48 khoản 2 – Nhận tiền qua tài khoản' },
],
quiz: [
{ q: 'Căn hộ hình thành trong tương lai giá 5 tỷ (ví dụ). Khách đã cọc 250 triệu. Đợt thanh toán khi ký hợp đồng tối đa là bao nhiêu để không vượt mốc lần đầu?', options: ['1,5 tỷ', '1,25 tỷ', '3,5 tỷ', '250 triệu'], answer: 1, why: 'Lần đầu không quá 30% giá trị hợp đồng (1,5 tỷ), bao gồm cả tiền cọc. Đã cọc 250 triệu thì chỉ được thu thêm tối đa 1,25 tỷ ở lần đầu.', ref: 'Điều 25 khoản 1 Luật Kinh doanh BĐS 2023' },
{ q: 'Chủ đầu tư trong nước được thu tối đa bao nhiêu % giá trị hợp đồng mua bán trước khi bàn giao căn hộ?', options: ['50%', '95%', '70%', '100%'], answer: 2, why: 'Tổng số tiền thu khi chưa bàn giao không quá 70% giá trị hợp đồng; mức 50% áp dụng khi bên bán là tổ chức kinh tế có vốn đầu tư nước ngoài thuộc diện luật định.', ref: 'Điều 25 khoản 1 Luật Kinh doanh BĐS 2023' },
{ q: 'Khách đã nhận nhà nhưng chưa được cấp sổ. Chủ đầu tư được thu tối đa bao nhiêu?', options: ['95% giá trị hợp đồng', '70% giá trị hợp đồng', '100% giá trị hợp đồng', '90% giá trị hợp đồng'], answer: 0, why: 'Nếu bên mua chưa được cấp Giấy chứng nhận thì bên bán không được thu quá 95%; phần còn lại thanh toán khi đã cấp sổ.', ref: 'Điều 25 khoản 3 Luật Kinh doanh BĐS 2023' },
{ q: 'Sau khi bàn giao căn hộ, chủ đầu tư phải nộp hồ sơ đề nghị cấp sổ cho người mua trong bao lâu?', options: ['30 ngày', '90 ngày', '6 tháng', '50 ngày, trừ khi người mua tự nguyện tự làm'], answer: 3, why: 'Trong 50 ngày kể từ ngày bàn giao nhà (hoặc từ khi bên thuê mua thanh toán đủ), chủ đầu tư phải nộp hồ sơ đề nghị cấp Giấy chứng nhận cho bên mua, trừ khi bên mua tự nguyện làm.', ref: 'Điều 17 khoản 3 Luật Kinh doanh BĐS 2023' },
{ q: 'Với hợp đồng thuê mua nhà ở hình thành trong tương lai, tổng tiền trả trước cho bên cho thuê mua tối đa là bao nhiêu?', options: ['30%', '50%', '70%', '95%'], answer: 1, why: 'Với thuê mua, lần đầu không quá 30% (gồm cọc), tổng tiền thanh toán trước không quá 50% giá trị hợp đồng; phần còn lại tính thành tiền thuê.', ref: 'Điều 25 khoản 2 Luật Kinh doanh BĐS 2023' },
{ q: 'Khách muốn đưa tiền mặt đợt 2 cho nhân viên kinh doanh để "nộp hộ". Sale nên làm gì?', options: ['Nhận và viết giấy biên nhận tay', 'Nhận nếu có người làm chứng', 'Từ chối, hướng dẫn khách chuyển khoản vào tài khoản của chủ đầu tư tại ngân hàng', 'Nhận rồi chuyển khoản lại cho chủ đầu tư'], answer: 2, why: 'Chủ đầu tư, doanh nghiệp kinh doanh BĐS nhận tiền thanh toán theo hợp đồng qua tài khoản mở tại tổ chức tín dụng. Sale giữ tiền mặt hộ khách là rủi ro lớn cho cả hai bên.', ref: 'Điều 48 khoản 2 Luật Kinh doanh BĐS 2023' },
],
},
{
id: 'pl09', group: 'phaply', level: 2, minutes: 7,
title: 'Bảo lãnh ngân hàng khi mua nhà hình thành trong tương lai',
intro: 'Thư bảo lãnh là "lưới an toàn" cho khách nếu chủ đầu tư không bàn giao nhà. Sale giải thích rõ cơ chế này giúp khách yên tâm hơn so với mọi lời hứa miệng.',
sections: [
{ h: 'Bảo lãnh cho nghĩa vụ gì', p: 'Trước khi bán nhà ở hình thành trong tương lai, chủ đầu tư phải được một ngân hàng thương mại trong nước hoặc chi nhánh ngân hàng nước ngoài chấp thuận cấp bảo lãnh. Ngân hàng bảo lãnh cho nghĩa vụ tài chính của chủ đầu tư khi không bàn giao nhà theo cam kết: tức số tiền khách đã ứng trước và khoản khác theo hợp đồng mà chủ đầu tư phải trả lại cho khách.' },
{ h: 'Thư bảo lãnh đến tay khách khi nào', p: 'Ngân hàng gửi văn bản cam kết phát hành thư bảo lãnh cho tất cả người mua trong dự án; chủ đầu tư gửi bản sao cam kết này khi ký hợp đồng. Thư bảo lãnh của từng khách được giao trong 10 ngày làm việc kể từ ngày ký hợp đồng (hoặc thời hạn khác hai bên thỏa thuận). Quan trọng: chủ đầu tư chỉ được nhận tiền thanh toán sau khi khách đã nhận thư bảo lãnh.' },
{ h: 'Khách có quyền chọn không bảo lãnh', p: 'Khi ký hợp đồng, người mua được lựa chọn có hoặc không có bảo lãnh. Nếu không lấy bảo lãnh thì phải thỏa thuận bằng văn bản tại thời điểm ký hợp đồng. Phạm vi, điều kiện, phí bảo lãnh do ngân hàng và chủ đầu tư thỏa thuận; thư bảo lãnh phải ghi thời hạn hiệu lực. Quy định bảo lãnh này không áp dụng cho nhà ở xã hội.' },
{ h: 'Cách tư vấn', p: 'Với căn hộ dự án ở Long Biên, sale nên đưa khách xem văn bản cam kết bảo lãnh của ngân hàng, giải thích thư bảo lãnh sẽ giao trong bao lâu, và nhắc khách đọc kỹ thời hạn hiệu lực. Nếu khách muốn bỏ bảo lãnh để được ưu đãi, hãy nói rõ khách sẽ mất lớp bảo vệ này nếu dự án chậm bàn giao.' },
],
exercise: 'Xin bản sao văn bản cam kết bảo lãnh của ngân hàng cho dự án anh/chị đang bán. Ghi lại tên ngân hàng, phạm vi bảo lãnh, thời hạn hiệu lực. Soạn 3 câu giải thích ngắn để đọc cho khách trong buổi tư vấn.',
takeaways: [
'Chủ đầu tư phải có ngân hàng chấp thuận bảo lãnh trước khi bán nhà hình thành trong tương lai.',
'Thư bảo lãnh giao khách trong 10 ngày làm việc từ ngày ký hợp đồng (hoặc theo thỏa thuận).',
'Chủ đầu tư chỉ được thu tiền sau khi khách nhận thư bảo lãnh.',
'Khách được chọn không bảo lãnh, nhưng phải thỏa thuận bằng văn bản; không áp dụng cho nhà ở xã hội.',
],
refs: [
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 26 – Bảo lãnh trong bán, cho thuê mua nhà ở hình thành trong tương lai' },
],
quiz: [
{ q: 'Ngân hàng bảo lãnh cho nghĩa vụ nào của chủ đầu tư?', options: ['Nghĩa vụ hoàn trả tiền khách đã ứng trước khi chủ đầu tư không bàn giao nhà theo cam kết', 'Nghĩa vụ bảo hành thang máy', 'Nghĩa vụ nộp thuế cho Nhà nước', 'Nghĩa vụ bảo đảm giá căn hộ không giảm'], answer: 0, why: 'Bảo lãnh dành cho nghĩa vụ tài chính của chủ đầu tư đối với bên mua khi không bàn giao nhà theo cam kết: số tiền đã ứng trước và khoản khác theo hợp đồng.', ref: 'Điều 26 khoản 1 Luật Kinh doanh BĐS 2023' },
{ q: 'Chủ đầu tư được nhận tiền thanh toán của khách theo hợp đồng từ thời điểm nào (với khách chọn có bảo lãnh)?', options: ['Ngay khi khách ký đặt cọc', 'Sau khi khách đã nhận được thư bảo lãnh của ngân hàng', 'Sau khi cất nóc', 'Sau khi bàn giao nhà'], answer: 1, why: 'Chủ đầu tư chỉ được nhận tiền thanh toán theo hợp đồng sau khi đã cung cấp và bên mua đã nhận được thư bảo lãnh.', ref: 'Điều 26 khoản 6 Luật Kinh doanh BĐS 2023' },
{ q: 'Thời hạn chủ đầu tư cung cấp thư bảo lãnh cho khách (nếu hai bên không thỏa thuận khác)?', options: ['30 ngày', '5 ngày làm việc', 'Khi bàn giao nhà', '10 ngày làm việc kể từ ngày ký hợp đồng'], answer: 3, why: 'Chủ đầu tư cung cấp thư bảo lãnh trong 10 ngày làm việc kể từ ngày ký hợp đồng mua bán hoặc thời hạn khác do các bên thỏa thuận.', ref: 'Điều 26 khoản 6 Luật Kinh doanh BĐS 2023' },
{ q: 'Khách muốn bỏ bảo lãnh để nhận chiết khấu. Điều này có được phép không?', options: ['Không, bảo lãnh là bắt buộc với mọi khách', 'Được, chỉ cần nói miệng với nhân viên', 'Được, nếu thỏa thuận bằng văn bản tại thời điểm ký hợp đồng', 'Chỉ được nếu ngân hàng đồng ý'], answer: 2, why: 'Bên mua được lựa chọn có hoặc không có bảo lãnh; việc từ chối bảo lãnh phải thỏa thuận bằng văn bản khi ký hợp đồng.', ref: 'Điều 26 khoản 3 Luật Kinh doanh BĐS 2023' },
{ q: 'Quy định bảo lãnh ngân hàng tại Điều 26 KHÔNG áp dụng cho loại nhà nào?', options: ['Căn hộ cao cấp', 'Nhà ở xã hội', 'Nhà liền kề trong dự án', 'Biệt thự trong dự án'], answer: 1, why: 'Luật ghi rõ quy định bảo lãnh trong bán, cho thuê mua nhà ở hình thành trong tương lai không áp dụng với nhà ở xã hội.', ref: 'Điều 26 khoản 8 Luật Kinh doanh BĐS 2023' },
{ q: 'Phí bảo lãnh và phạm vi bảo lãnh do ai thỏa thuận?', options: ['Ngân hàng bảo lãnh và chủ đầu tư, ghi vào thỏa thuận cấp bảo lãnh', 'Người mua và sàn giao dịch', 'Do Nhà nước ấn định một mức chung', 'Do nhân viên môi giới đề xuất'], answer: 0, why: 'Phạm vi, điều kiện, nội dung và phí bảo lãnh do các bên thỏa thuận và ghi vào thỏa thuận cấp bảo lãnh giữa ngân hàng và chủ đầu tư; thư bảo lãnh phải ghi thời hạn hiệu lực.', ref: 'Điều 26 khoản 5 Luật Kinh doanh BĐS 2023' },
],
},
{
id: 'pl10', group: 'phaply', level: 2, minutes: 8,
title: 'Hợp đồng mẫu và chuyển nhượng hợp đồng mua bán căn hộ',
intro: 'Khách mua căn hộ dự án hay muốn "sang tay" trước khi có sổ. Sale cần biết hợp đồng mẫu bảo vệ khách thế nào và điều kiện để chuyển nhượng hợp đồng hợp pháp.',
sections: [
{ h: 'Hợp đồng mẫu không được tự ý sửa', p: 'Chính phủ ban hành các hợp đồng mẫu trong kinh doanh BĐS (Nghị định 96/2024, hợp đồng mua bán, thuê mua nhà ở theo Phụ lục I). Doanh nghiệp phải tuân thủ đúng, không được thay đổi nội dung đã có trong mẫu; phần được bổ sung không được trái hoặc làm thay đổi nội dung mẫu; hợp đồng phải được công khai trước khi dùng để ký. Ký sai mẫu thì doanh nghiệp bị xử lý và phải bồi thường cho khách.' },
{ h: 'Hợp đồng nào được chuyển nhượng', p: 'Luật cho phép chuyển nhượng hợp đồng mua bán, thuê mua nhà ở hình thành trong tương lai và hợp đồng thuê mua công trình có sẵn. Điều kiện: chưa nộp hồ sơ đề nghị cấp Giấy chứng nhận; hợp đồng không có tranh chấp đang được giải quyết; nhà không bị kê biên, thế chấp (trừ khi bên nhận thế chấp đồng ý); hợp đồng được xác lập đúng luật. Phải chuyển nhượng toàn bộ hợp đồng; quy định này không áp dụng cho nhà ở xã hội.' },
{ h: 'Thủ tục: công chứng rồi chủ đầu tư xác nhận', p: 'Hai bên lập hợp đồng chuyển nhượng theo mẫu Phụ lục XI, ít nhất 06 bản; công chứng tại tổ chức hành nghề công chứng ở tỉnh có BĐS (nếu bên chuyển nhượng là doanh nghiệp kinh doanh BĐS thì không bắt buộc công chứng); nộp thuế, phí; rồi nộp hồ sơ cho chủ đầu tư xác nhận. Chủ đầu tư phải tạo điều kiện và không được thu bất kỳ khoản phí nào cho việc chuyển nhượng hợp đồng.' },
{ h: 'Khi nào hết đường chuyển nhượng hợp đồng', p: 'Khi hồ sơ cấp sổ cho người mua đã nộp lên cơ quan nhà nước thì không chuyển nhượng hợp đồng được nữa. Ví dụ khách ở dự án Mễ Trì muốn bán lại: nếu chủ đầu tư đã nộp hồ sơ cấp sổ, khách phải chờ có sổ rồi bán như nhà có sẵn (công chứng hợp đồng mua bán, sang tên).' },
],
exercise: 'Đọc hợp đồng mua bán của dự án anh/chị đang bán, đối chiếu với mẫu Phụ lục I Nghị định 96/2024. Ghi lại 3 điều khoản quan trọng với khách (tiến độ thanh toán, phạt chậm bàn giao, thời hạn làm sổ) để giải thích trong buổi ký.',
takeaways: [
'Doanh nghiệp không được thay đổi nội dung hợp đồng mẫu; phải công khai trước khi ký.',
'Chỉ chuyển nhượng hợp đồng khi chưa nộp hồ sơ cấp sổ.',
'Phải chuyển nhượng toàn bộ hợp đồng; chủ đầu tư không được thu phí.',
'Bên chuyển nhượng là cá nhân thì hợp đồng chuyển nhượng phải công chứng.',
],
refs: [
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 44 khoản 7 – Hợp đồng mẫu' },
{ t: 'Luật Kinh doanh bất động sản 2023 (số 29/2023/QH15), Điều 49, Điều 50, Điều 51 – Chuyển nhượng hợp đồng' },
{ t: 'Nghị định 96/2024/NĐ-CP (sửa đổi bởi 54/2026/NĐ-CP), Điều 12, Điều 13 – Hợp đồng mẫu, thủ tục chuyển nhượng hợp đồng' },
],
quiz: [
{ q: 'Khách mua căn hộ hình thành trong tương lai muốn chuyển nhượng hợp đồng. Điều kiện quan trọng nhất về thời điểm là gì?', options: ['Chưa nộp hồ sơ đề nghị cấp Giấy chứng nhận cho bên mua', 'Đã nhận bàn giao nhà', 'Đã thanh toán đủ 95%', 'Đã có sổ hồng'], answer: 0, why: 'Chuyển nhượng hợp đồng chỉ được thực hiện khi hồ sơ đề nghị cấp Giấy chứng nhận chưa được nộp cho cơ quan nhà nước có thẩm quyền.', ref: 'Điều 50 khoản 1 điểm a Luật Kinh doanh BĐS 2023' },
{ q: 'Chủ đầu tư đòi thu "phí xác nhận chuyển nhượng hợp đồng" 1% giá trị căn. Đúng hay sai?', options: ['Đúng, vì chủ đầu tư phải làm thủ tục', 'Đúng nếu ghi trong quy chế dự án', 'Sai, chủ đầu tư không được thu bất kỳ khoản chi phí nào liên quan đến chuyển nhượng hợp đồng', 'Đúng nếu khách đồng ý'], answer: 2, why: 'Chủ đầu tư có trách nhiệm tạo điều kiện và không được thu bất kỳ khoản chi phí nào liên quan đến việc chuyển nhượng hợp đồng.', ref: 'Điều 51 khoản 2 Luật Kinh doanh BĐS 2023' },
{ q: 'Khách mua 2 căn trong cùng một hợp đồng, muốn chuyển nhượng 1 căn. Phải làm gì?', options: ['Chuyển nhượng một phần hợp đồng ngay', 'Sửa đổi hợp đồng hoặc ký phụ lục tách căn trước, rồi chuyển nhượng', 'Không bao giờ được chuyển nhượng', 'Chỉ cần sàn xác nhận'], answer: 1, why: 'Chuyển nhượng hợp đồng thực hiện với toàn bộ hợp đồng; nếu nhiều căn trong một hợp đồng mà muốn chuyển từng căn thì phải sửa hợp đồng hoặc ký phụ lục trước.', ref: 'Điều 50 khoản 2 Luật Kinh doanh BĐS 2023' },
{ q: 'Bên chuyển nhượng hợp đồng là cá nhân. Hợp đồng chuyển nhượng hợp đồng có phải công chứng không?', options: ['Không, chỉ cần chủ đầu tư ký xác nhận', 'Chỉ cần lập vi bằng', 'Chỉ công chứng nếu giá trên 5 tỷ', 'Có, công chứng tại tổ chức hành nghề công chứng ở tỉnh nơi có BĐS'], answer: 3, why: 'Hồ sơ đề nghị tổ chức hành nghề công chứng tại tỉnh nơi có BĐS chứng nhận hợp đồng chuyển nhượng; chỉ khi bên chuyển nhượng là doanh nghiệp có ngành nghề kinh doanh BĐS mới không bắt buộc công chứng.', ref: 'Điều 13 khoản 2 điểm b Nghị định 96/2024/NĐ-CP' },
{ q: 'Doanh nghiệp tự thêm vào hợp đồng mẫu điều khoản bỏ phạt chậm bàn giao. Đánh giá đúng?', options: ['Không đúng, vì phần bổ sung không được làm thay đổi hoặc trái nội dung hợp đồng mẫu', 'Hợp lệ, doanh nghiệp được tự do thỏa thuận', 'Hợp lệ nếu khách ký', 'Hợp lệ nếu đã công khai trên website'], answer: 0, why: 'Doanh nghiệp không được thay đổi nội dung trong hợp đồng mẫu; phần được bổ sung phải không trái, không làm thay đổi nội dung đã có. Ký sai mẫu thì bị xử lý và phải bồi thường cho khách.', ref: 'Điều 12 khoản 3 Nghị định 96/2024/NĐ-CP' },
{ q: 'Hợp đồng nào sau đây KHÔNG thuộc diện được chuyển nhượng hợp đồng theo Luật Kinh doanh BĐS?', options: ['Hợp đồng mua bán nhà ở hình thành trong tương lai', 'Hợp đồng thuê mua nhà ở hình thành trong tương lai', 'Hợp đồng mua bán nhà ở xã hội', 'Hợp đồng thuê mua công trình xây dựng có sẵn'], answer: 2, why: 'Quy định chuyển nhượng hợp đồng tại Mục 2 Chương VI không áp dụng đối với hợp đồng mua bán, thuê mua nhà ở xã hội.', ref: 'Điều 49 khoản 2 Luật Kinh doanh BĐS 2023' },
],
},
{
id: 'pl11', group: 'phaply', level: 2, minutes: 8,
title: 'Chung cư: thời hạn sử dụng, cải tạo và phí bảo trì 2%',
intro: 'Câu "chung cư chỉ ở được 50 năm" làm nhiều khách ngần ngại. Sale cần nói đúng luật về thời hạn sử dụng nhà chung cư, khi nào phải cải tạo và khoản bảo trì 2% đi đâu.',
sections: [
{ h: 'Không có mốc "50 năm" cho người Việt', p: 'Luật Nhà ở 2023 xác định thời hạn sử dụng nhà chung cư theo hồ sơ thiết kế và thời gian sử dụng thực tế theo kết luận kiểm định, tính từ khi nghiệm thu đưa vào sử dụng. Quyền sử dụng đất ở là ổn định lâu dài. Vì vậy với khách mua căn hộ để ở tại Cầu Giấy, sale không nên nói "sổ hồng 50 năm"; mốc 50 năm là thời hạn sở hữu của cá nhân nước ngoài, hoặc thường gặp với đất thương mại dịch vụ có thời hạn.' },
{ h: 'Khi nào chung cư phải phá dỡ, xây lại', p: 'Khi hết thời hạn theo thiết kế, hoặc chưa hết nhưng hư hỏng, có nguy cơ sập đổ, UBND cấp tỉnh chỉ đạo kiểm định chất lượng. Chung cư phải phá dỡ khi bị hư hỏng do cháy nổ, thiên tai, kết cấu chịu lực nguy hiểm… Việc cải tạo, xây lại thực hiện theo dự án và quy hoạch; nếu theo quy hoạch vẫn xây lại chung cư thì chủ sở hữu được tái định cư tại chỗ, trừ khi không có nhu cầu. Ví dụ các khu tập thể cũ ở Hà Nội đang được cải tạo theo cơ chế này.' },
{ h: 'Phí bảo trì 2%: tính riêng, có tài khoản riêng', p: 'Người mua căn hộ của chủ đầu tư phải đóng kinh phí bảo trì bằng 2% giá trị căn hộ; khoản này tính riêng với tiền mua và ghi rõ trong hợp đồng. Căn chủ đầu tư giữ lại hoặc chưa bán khi bàn giao, chủ đầu tư cũng phải đóng 2%. Trước khi ký hợp đồng, chủ đầu tư phải mở tài khoản tại tổ chức tín dụng để người mua nộp khoản này, sau đó bàn giao cho Ban quản trị nhà chung cư quản lý.' },
{ h: 'Nói với khách thế nào', p: 'Ví dụ căn 3 tỷ (ví dụ) thì phí bảo trì 2% là 60 triệu, nộp riêng ngoài giá mua. Khi so sánh giá giữa các dự án, hãy hỏi giá đã gồm hay chưa gồm 2% bảo trì để khách không bị bất ngờ. Với căn mua lại từ cư dân, kiểm tra người bán đã nộp đủ phí bảo trì chưa. Luật Nhà ở (sửa đổi) đã thông qua ngày 21/11/2026, ngày hiệu lực theo văn bản khi được công bố; trước khi luật mới có hiệu lực, áp dụng Luật 27/2023/QH15.' },
],
exercise: 'Chọn 2 dự án chung cư trong giỏ hàng. Ghi rõ giá đã gồm hay chưa gồm 2% phí bảo trì, tài khoản bảo trì mở tại ngân hàng nào, Ban quản trị đã thành lập chưa. Soạn một câu trả lời chuẩn cho câu hỏi "chung cư ở được bao nhiêu năm?".',
takeaways: [
'Thời hạn sử dụng chung cư theo hồ sơ thiết kế và kết luận kiểm định, không phải mốc cố định 50 năm.',
'Hết hạn hoặc hư hỏng nguy hiểm thì kiểm định; có trường hợp phải phá dỡ, xây lại theo dự án.',
'Phí bảo trì 2% giá trị căn hộ, tính riêng ngoài giá bán, ghi trong hợp đồng.',
'Chủ đầu tư mở tài khoản bảo trì trước khi ký hợp đồng và bàn giao cho Ban quản trị.',
],
refs: [
{ t: 'Luật Nhà ở 2023 (số 27/2023/QH15), Điều 58 – Thời hạn sử dụng nhà chung cư' },
{ t: 'Luật Nhà ở 2023 (số 27/2023/QH15), Điều 59, Điều 60 – Phá dỡ, cải tạo, xây dựng lại nhà chung cư' },
{ t: 'Luật Nhà ở 2023 (số 27/2023/QH15), Điều 152, Điều 153 – Kinh phí bảo trì' },
{ t: 'Luật Đất đai 2024 (số 31/2024/QH15), Điều 171 khoản 1 – Đất ở sử dụng ổn định lâu dài' },
],
quiz: [
{ q: 'Theo Luật Nhà ở 2023, thời hạn sử dụng nhà chung cư được xác định thế nào?', options: ['Cố định 50 năm cho mọi chung cư', '70 năm kể từ ngày cấp sổ', 'Theo hồ sơ thiết kế và thời gian sử dụng thực tế theo kết luận kiểm định', 'Do Ban quản trị quyết định'], answer: 2, why: 'Thời hạn sử dụng nhà chung cư xác định theo hồ sơ thiết kế và thời gian sử dụng thực tế theo kết luận kiểm định của cơ quan có thẩm quyền.', ref: 'Điều 58 khoản 1 Luật Nhà ở 2023' },
{ q: 'Thời hạn sử dụng nhà chung cư được tính từ thời điểm nào?', options: ['Từ khi nghiệm thu nhà chung cư đưa vào sử dụng', 'Từ ngày khởi công', 'Từ ngày người mua nhận sổ', 'Từ ngày ký hợp đồng mua bán'], answer: 0, why: 'Thời hạn sử dụng nhà chung cư được tính từ khi nghiệm thu đưa vào sử dụng theo pháp luật xây dựng.', ref: 'Điều 58 khoản 2 Luật Nhà ở 2023' },
{ q: 'Căn hộ mua của chủ đầu tư giá 3 tỷ (ví dụ, chưa gồm bảo trì). Khách phải nộp kinh phí bảo trì bao nhiêu?', options: ['30 triệu', '90 triệu', 'Không phải nộp, đã gồm trong giá', '60 triệu, tính riêng ngoài giá bán'], answer: 3, why: 'Người mua phải đóng kinh phí bảo trì 2% giá trị căn hộ; khoản này tính riêng với tiền bán và ghi rõ trong hợp đồng. 2% của 3 tỷ là 60 triệu.', ref: 'Điều 152 khoản 1 Luật Nhà ở 2023' },
{ q: 'Căn hộ chủ đầu tư chưa bán được khi bàn giao tòa nhà thì ai đóng 2% bảo trì?', options: ['Không ai đóng cho đến khi bán được', 'Chủ đầu tư phải đóng 2%, tính theo giá bán cao nhất của tòa tại thời điểm bàn giao', 'Ban quản trị đóng thay', 'Cư dân đóng chung'], answer: 1, why: 'Với căn chủ đầu tư giữ lại hoặc chưa bán tại thời điểm bàn giao, chủ đầu tư phải đóng 2%, tính theo giá bán căn hộ có giá cao nhất của nhà chung cư tại thời điểm đó.', ref: 'Điều 152 khoản 2 Luật Nhà ở 2023' },
{ q: 'Chung cư cũ phải xây lại, quy hoạch vẫn là chung cư. Quyền của chủ sở hữu căn hộ là gì?', options: ['Chỉ được bồi thường tiền', 'Phải mua lại căn mới theo giá thị trường', 'Được tái định cư tại chỗ, trừ trường hợp không có nhu cầu', 'Mất quyền sở hữu khi tòa hết hạn'], answer: 2, why: 'Nếu theo quy hoạch tiếp tục xây dựng lại nhà chung cư thì các chủ sở hữu được tái định cư tại chỗ, trừ trường hợp không có nhu cầu.', ref: 'Điều 60 khoản 4 Luật Nhà ở 2023' },
{ q: 'Khách hỏi: "Chung cư cũ có bị Nhà nước lấy lại khi hết 50 năm không?" Câu trả lời đúng tinh thần luật?', options: ['Có, đến 50 năm là thu hồi', 'Không có mốc 50 năm; khi hết thời hạn theo thiết kế hoặc hư hỏng thì kiểm định, nếu phải phá dỡ thì cải tạo, xây lại theo dự án với phương án bồi thường, tái định cư', 'Có, nhưng được gia hạn 1 lần', 'Không bao giờ phải phá dỡ'], answer: 1, why: 'Luật quy định kiểm định khi hết thời hạn theo thiết kế hoặc có nguy cơ mất an toàn; trường hợp phải phá dỡ thì cải tạo, xây lại theo dự án, có phương án bồi thường, tái định cư.', ref: 'Điều 58, Điều 59, Điều 60 Luật Nhà ở 2023' },
],
},
{
id: 'pl12', group: 'phaply', level: 3, minutes: 8,
title: 'Người nước ngoài và Việt kiều mua nhà tại Việt Nam',
intro: 'Khách nước ngoài thuê, mua căn hộ ở Tây Hồ, Ba Đình ngày càng nhiều. Một câu tư vấn sai (ví dụ bán nhà phố ngoài dự án cho người nước ngoài) có thể khiến giao dịch không được công nhận.',
sections: [
{ h: 'Ai được mua và mua loại nhà nào', p: 'Cá nhân nước ngoài được phép nhập cảnh vào Việt Nam (không thuộc diện ưu đãi, miễn trừ ngoại giao) được sở hữu nhà ở thương mại trong dự án đầu tư xây dựng nhà ở, gồm căn hộ và nhà ở riêng lẻ, thông qua mua, thuê mua, nhận tặng cho, thừa kế. Dự án phải không thuộc khu vực cần bảo đảm quốc phòng, an ninh; danh mục dự án cho phép được UBND cấp tỉnh công bố. Người nước ngoài không mua được nhà phố, đất thổ cư ngoài dự án.' },
{ h: 'Giới hạn số lượng', p: 'Người nước ngoài chỉ được sở hữu không quá 30% số căn hộ trong một tòa chung cư; với nhà ở riêng lẻ (biệt thự, liền kề) thì trên một khu vực có quy mô dân số tương đương một phường không quá 250 căn. Khi tòa đã đủ 30% căn của người nước ngoài, khách nước ngoài tiếp theo không được mua, sở hữu thêm căn trong tòa đó, sale cần kiểm tra trước với chủ đầu tư.' },
{ h: 'Thời hạn sở hữu 50 năm, gia hạn 1 lần', p: 'Cá nhân nước ngoài sở hữu nhà ở tối đa 50 năm kể từ ngày được cấp Giấy chứng nhận, được gia hạn một lần không quá 50 năm; thời hạn ghi trên sổ. Người nước ngoài kết hôn với công dân Việt Nam đang sinh sống tại Việt Nam được sở hữu như công dân Việt Nam. Trước khi cho thuê căn hộ, chủ là cá nhân nước ngoài phải thông báo với cơ quan quản lý nhà ở và nộp thuế cho thuê.' },
{ h: 'Việt kiều: phân biệt quốc tịch', p: 'Người Việt Nam định cư ở nước ngoài còn quốc tịch Việt Nam được xem như cá nhân trong nước theo Luật Đất đai, mua được nhà đất như người trong nước. Người gốc Việt không còn quốc tịch Việt Nam, được phép nhập cảnh, thì được mua nhà ở gắn với quyền sử dụng đất ở trong dự án phát triển nhà ở, được nhận thừa kế, và nhận tặng cho nhà ở từ người thuộc hàng thừa kế. Sale nên hỏi khách hộ chiếu Việt Nam còn hiệu lực hay giấy tờ chứng minh quốc tịch trước khi tư vấn. Luật Đất đai (sửa đổi) đã thông qua ngày 21/11/2026, hiệu lực từ 01/07/2027; Luật Nhà ở (sửa đổi) cũng đã thông qua cùng ngày. Trước khi luật mới có hiệu lực, áp dụng quy định hiện hành.' },
],
exercise: 'Với dự án căn hộ anh/chị đang bán, hỏi chủ đầu tư: dự án có trong danh mục cho người nước ngoài sở hữu không, mỗi tòa còn bao nhiêu suất trong hạn mức 30%. Lưu thông tin vào ghi chú dự án để trả lời khách nước ngoài trong 1 phút.',
takeaways: [
'Người nước ngoài chỉ mua nhà ở thương mại trong dự án, không mua nhà đất ngoài dự án.',
'Tối đa 30% căn hộ mỗi tòa; nhà riêng lẻ tối đa 250 căn trên khu vực tương đương một phường.',
'Thời hạn sở hữu tối đa 50 năm từ ngày cấp sổ, gia hạn 1 lần.',
'Việt kiều còn quốc tịch Việt Nam có quyền như cá nhân trong nước.',
],
refs: [
{ t: 'Luật Nhà ở 2023 (số 27/2023/QH15), Điều 8, Điều 16, Điều 17, Điều 18 – Đối tượng, khu vực, hình thức sở hữu' },
{ t: 'Luật Nhà ở 2023 (số 27/2023/QH15), Điều 19, Điều 20, Điều 21 – Số lượng, quyền và nghĩa vụ của người nước ngoài' },
{ t: 'Luật Đất đai 2024 (số 31/2024/QH15), Điều 4 khoản 3, Điều 28 khoản 1 điểm h – Người Việt Nam định cư ở nước ngoài' },
],
quiz: [
{ q: 'Khách người Hàn Quốc muốn mua một nhà phố trong ngõ ở Đống Đa (không thuộc dự án). Sale tư vấn đúng là gì?', options: ['Mua được nếu thanh toán bằng ngoại tệ', 'Mua được nếu nhờ người Việt đứng tên hộ', 'Mua được nếu có thẻ tạm trú', 'Không mua được; người nước ngoài chỉ sở hữu nhà ở thương mại trong dự án đầu tư xây dựng nhà ở'], answer: 3, why: 'Cá nhân nước ngoài sở hữu nhà ở thông qua mua, thuê mua nhà ở thương mại trong dự án không thuộc khu vực quốc phòng, an ninh. Đứng tên hộ là rủi ro pháp lý lớn, không nên tư vấn.', ref: 'Điều 17 khoản 2 Luật Nhà ở 2023' },
{ q: 'Người nước ngoài được sở hữu tối đa bao nhiêu căn hộ trong một tòa chung cư?', options: ['30% số căn hộ của tòa', '50% số căn hộ', '10% số căn hộ', '250 căn mỗi tòa'], answer: 0, why: 'Tổ chức, cá nhân nước ngoài chỉ được sở hữu không quá 30% số lượng căn hộ trong một tòa nhà chung cư. Mốc 250 căn áp dụng cho nhà ở riêng lẻ trên khu vực tương đương một phường.', ref: 'Điều 19 khoản 1 Luật Nhà ở 2023' },
{ q: 'Thời hạn sở hữu nhà ở của cá nhân nước ngoài (không kết hôn với công dân Việt Nam) là bao lâu?', options: ['Vô thời hạn', 'Tối đa 50 năm từ ngày cấp Giấy chứng nhận, được gia hạn 1 lần không quá 50 năm', '70 năm, không gia hạn', 'Bằng thời hạn visa'], answer: 1, why: 'Cá nhân nước ngoài sở hữu nhà theo thỏa thuận nhưng không quá 50 năm kể từ ngày cấp Giấy chứng nhận, được gia hạn một lần không quá 50 năm; thời hạn ghi trên sổ.', ref: 'Điều 20 khoản 2 điểm c Luật Nhà ở 2023' },
{ q: 'Anh John (quốc tịch Úc) kết hôn với chị Hoa (công dân Việt Nam), hai người đang sống tại Hà Nội. Quyền sở hữu nhà của anh John thế nào?', options: ['Như mọi cá nhân nước ngoài khác, tối đa 50 năm', 'Không được sở hữu nhà', 'Được sở hữu nhà ở và có quyền của chủ sở hữu như công dân Việt Nam', 'Chỉ được đứng tên chung với vợ'], answer: 2, why: 'Cá nhân nước ngoài kết hôn với công dân Việt Nam đang sinh sống tại Việt Nam được sở hữu nhà ở và có quyền của chủ sở hữu như công dân Việt Nam.', ref: 'Điều 20 khoản 2 điểm c Luật Nhà ở 2023' },
{ q: 'Việt kiều Mỹ vẫn còn quốc tịch Việt Nam muốn mua đất thổ cư ở Đông Anh. Theo Luật Đất đai 2024 thì sao?', options: ['Không được, chỉ mua được căn hộ dự án', 'Được, vì người Việt Nam định cư ở nước ngoài là công dân Việt Nam được xem như cá nhân trong nước', 'Chỉ được nếu về nước định cư', 'Chỉ được nhận thừa kế, không được mua'], answer: 1, why: 'Luật Đất đai 2024 gộp cá nhân trong nước và người Việt Nam định cư ở nước ngoài là công dân Việt Nam vào nhóm "cá nhân", có quyền nhận chuyển nhượng như nhau.', ref: 'Điều 4 khoản 3 Luật Đất đai 2024' },
{ q: 'Cá nhân nước ngoài sở hữu căn hộ muốn cho thuê. Nghĩa vụ trước khi cho thuê là gì?', options: ['Không cần làm gì', 'Phải xin phép Bộ Ngoại giao', 'Chỉ cần báo Ban quản trị tòa nhà', 'Thông báo bằng văn bản với cơ quan quản lý nhà ở nơi có nhà và nộp thuế cho thuê theo quy định'], answer: 3, why: 'Chủ sở hữu là cá nhân nước ngoài được cho thuê nhà nhưng trước khi cho thuê phải có văn bản thông báo với cơ quan quản lý nhà ở nơi có nhà và nộp thuế từ hoạt động cho thuê.', ref: 'Điều 21 khoản 2 điểm a Luật Nhà ở 2023' },
],
},
{
id: 'pl13', group: 'phaply', level: 3, minutes: 9,
title: 'Đất vườn, đất nông nghiệp: chuyển mục đích và tách thửa',
intro: 'Khách mua đất vùng ven Hà Nội (Đông Anh, Gia Lâm, Hoài Đức) thường hỏi "lên thổ cư được không, tách lô được không". Đây là nhóm câu hỏi dễ tư vấn sai nhất vì phụ thuộc cả luật lẫn quy định địa phương.',
sections: [
{ h: 'Trường hợp nào phải xin phép chuyển mục đích', p: 'Phải được cơ quan có thẩm quyền cho phép khi chuyển đất nông nghiệp sang đất phi nông nghiệp, chuyển đất phi nông nghiệp không phải đất ở sang đất ở, hoặc chuyển đất trồng lúa, đất rừng sang loại đất nông nghiệp khác. Việc cho phép phải phù hợp quy hoạch. Từ 01/07/2025 không còn cấp huyện; theo Nghị định 151/2025/NĐ-CP, hồ sơ cá nhân xin chuyển mục đích được giải quyết ở cấp xã nơi có đất. Quy định phân cấp này có thể được điều chỉnh, nên hỏi bộ phận một cửa của xã, phường trước khi nộp. Sale không bao giờ khẳng định "chắc lên được thổ cư" khi chưa tra quy hoạch.' },
{ h: 'Tiền sử dụng đất khi lên đất ở từ 2026', p: 'Người sử dụng đất phải thực hiện nghĩa vụ tài chính khi chuyển mục đích. Theo Nghị quyết 254/2025/QH15 (hiệu lực 01/01/2026), với đất vườn, ao, đất nông nghiệp trong cùng thửa có đất ở (và một số trường hợp tách thửa trước 01/07/2014) chuyển sang đất ở: nộp 30% chênh lệch tiền sử dụng đất cho diện tích trong hạn mức giao đất ở; 50% cho phần vượt không quá 1 lần hạn mức; 100% cho phần vượt hơn nữa; chỉ tính một lần cho một hộ, một thửa. Các trường hợp khác nộp theo mức chênh lệch đầy đủ.' },
{ h: 'Giới hạn nhận chuyển nhượng đất nông nghiệp', p: 'Hạn mức nhận chuyển quyền sử dụng đất nông nghiệp của cá nhân không quá 15 lần hạn mức giao đất nông nghiệp cho mỗi loại đất (tỉnh, thành không thuộc Đông Nam Bộ, ĐBSCL như Hà Nội: hạn mức giao đất trồng cây hằng năm tối đa 2 ha). Cá nhân không trực tiếp sản xuất nông nghiệp muốn nhận chuyển nhượng đất trồng lúa vượt hạn mức phải thành lập tổ chức kinh tế và có phương án sử dụng đất được phê duyệt.' },
{ h: 'Tách thửa, hợp thửa: luật chung và quy định Hà Nội', p: 'Tách thửa cần: đã có sổ, còn thời hạn, không tranh chấp, kê biên; có lối đi kết nối đường giao thông công cộng; mỗi thửa sau tách đạt diện tích tối thiểu do UBND cấp tỉnh quy định. Nghị quyết 254/2025/QH15 nới thêm: lối đi có thể qua đất liền kề nếu được chủ đất đồng ý; chuyển mục đích một phần thửa không bắt buộc tách thửa; hợp thửa không bắt buộc cùng mục đích, thời hạn. Ở Hà Nội, đất ở tại phường thường cần tối thiểu 50 m², mặt tiền và chiều sâu từ 4 m theo quyết định của UBND Thành phố; xã có mức cao hơn. Luôn kiểm tra văn bản mới nhất của Thành phố trước khi báo khách. Luật Đất đai (sửa đổi) đã thông qua ngày 21/11/2026, hiệu lực từ 01/07/2027; trước ngày đó áp dụng Luật 31/2024/QH15 và Nghị quyết 254/2025/QH15.' },
],
exercise: 'Chọn một lô đất vườn ở vùng ven đang có trong giỏ hàng. Ghi: diện tích đất ở và đất vườn trên sổ, quy hoạch sử dụng đất của thửa, diện tích tối thiểu tách thửa áp dụng. Ước tính (ví dụ) tiền chuyển mục đích theo mốc 30% – 50% – 100% và ghi rõ đây là ước tính cần cơ quan thuế xác định.',
takeaways: [
'Đất nông nghiệp sang đất ở phải được phép, phải phù hợp quy hoạch; cá nhân nộp hồ sơ tại cấp xã nơi có đất.',
'Từ 2026, đất vườn ao cùng thửa đất ở lên thổ cư: 30% chênh lệch trong hạn mức, 50% vượt đến 1 lần, 100% phần còn lại.',
'Nhận chuyển nhượng đất nông nghiệp tối đa 15 lần hạn mức giao.',
'Tách thửa theo diện tích tối thiểu của UBND tỉnh; Nghị quyết 254 nới điều kiện lối đi và hợp thửa.',
],
refs: [
{ t: 'Luật Đất đai 2024 (số 31/2024/QH15), Điều 121 – Chuyển mục đích sử dụng đất' },
{ t: 'Luật Đất đai 2024 (số 31/2024/QH15), Điều 45 khoản 7, Điều 176, Điều 177 – Hạn mức đất nông nghiệp' },
{ t: 'Luật Đất đai 2024 (số 31/2024/QH15), Điều 220 – Tách thửa, hợp thửa' },
{ t: 'Nghị quyết 254/2025/QH15, Điều 10 khoản 2, Điều 11 khoản 3 – Tiền sử dụng đất khi chuyển mục đích; tách, hợp thửa' },
],
quiz: [
{ q: 'Trường hợp nào sau đây KHÔNG phải xin phép cơ quan nhà nước khi chuyển mục đích?', options: ['Chuyển đất trồng cây lâu năm sang đất ở', 'Chuyển đất thương mại, dịch vụ sang đất ở', 'Chuyển đất trồng lúa sang đất nuôi trồng thủy sản', 'Chuyển đất trồng cây hằng năm khác sang đất trồng cây lâu năm'], answer: 3, why: 'Phải xin phép khi chuyển đất lúa, đất rừng sang loại nông nghiệp khác; nông nghiệp sang phi nông nghiệp; phi nông nghiệp không phải đất ở sang đất ở. Chuyển giữa cây hằng năm khác và cây lâu năm không thuộc danh sách phải xin phép.', ref: 'Điều 121 khoản 1, khoản 3 Luật Đất đai 2024' },
{ q: 'Thửa đất có 100 m² đất ở và 200 m² đất vườn cùng thửa. Năm 2026 chủ muốn chuyển 150 m² vườn sang đất ở, trong hạn mức giao đất ở. Mức thu tiền sử dụng đất theo Nghị quyết 254/2025/QH15?', options: ['30% chênh lệch giữa giá đất ở và giá đất nông nghiệp', '100% chênh lệch', '50% chênh lệch', 'Miễn hoàn toàn'], answer: 0, why: 'Với đất vườn, ao trong cùng thửa có đất ở chuyển sang đất ở, phần trong hạn mức giao đất ở nộp 30% chênh lệch; vượt không quá 1 lần hạn mức: 50%; vượt hơn: 100%; chỉ tính một lần cho một hộ, một thửa.', ref: 'Điều 10 khoản 2 điểm c Nghị quyết 254/2025/QH15' },
{ q: 'Từ 01/07/2025, cá nhân xin chuyển đất vườn sang đất ở nộp hồ sơ và do cấp nào quyết định?', options: ['Bộ Nông nghiệp và Môi trường', 'Chủ tịch UBND cấp huyện', 'UBND cấp xã nơi có đất', 'Thủ tướng Chính phủ'], answer: 2, why: 'Từ 01/07/2025 không còn cấp huyện; theo Nghị định 151/2025/NĐ-CP về phân định thẩm quyền chính quyền 2 cấp, việc cho phép cá nhân chuyển mục đích sử dụng đất do cấp xã nơi có đất giải quyết.' },
{ q: 'Muốn tách một thửa đất ở thành hai lô, điều kiện nào là bắt buộc?', options: ['Phải có ít nhất 2 người đứng tên', 'Các thửa sau tách đạt diện tích tối thiểu do UBND cấp tỉnh quy định và có lối đi kết nối đường công cộng', 'Phải xây nhà trên cả hai lô trước', 'Phải được tổ dân phố đồng ý'], answer: 1, why: 'Tách thửa cần đã có sổ, còn thời hạn, không tranh chấp, kê biên, có lối đi, và mỗi thửa sau tách đạt diện tích tối thiểu theo quy định của UBND cấp tỉnh.', ref: 'Điều 220 khoản 1, khoản 2 Luật Đất đai 2024' },
{ q: 'Thửa đất ở trong ngõ không có lối đi riêng, nhưng hàng xóm đồng ý cho đi qua đất của họ ra đường chung. Theo Nghị quyết 254/2025/QH15, điều kiện lối đi khi tách thửa?', options: ['Vẫn không đạt, phải có lối đi riêng trên chính thửa đất', 'Chỉ đạt nếu Nhà nước mở đường', 'Chỉ đạt nếu mua lại lối đi', 'Đạt, vì có thể có lối đi qua đất liền kề nếu được người sử dụng đất liền kề đồng ý'], answer: 3, why: 'Nghị quyết 254 cho phép tách, hợp thửa khi có lối đi kết nối đường công cộng hoặc được người sử dụng đất liền kề đồng ý cho đi qua để kết nối.', ref: 'Điều 11 khoản 3 Nghị quyết 254/2025/QH15' },
{ q: 'Hạn mức nhận chuyển quyền sử dụng đất nông nghiệp của một cá nhân tối đa là bao nhiêu?', options: ['Không quá 15 lần hạn mức giao đất nông nghiệp cho mỗi loại đất', 'Không giới hạn', '5 lần hạn mức giao', '2 ha cho tất cả các loại đất'], answer: 0, why: 'Hạn mức nhận chuyển quyền sử dụng đất nông nghiệp của cá nhân không quá 15 lần hạn mức giao đất nông nghiệp đối với mỗi loại đất; UBND cấp tỉnh quy định cụ thể.', ref: 'Điều 177 khoản 1 Luật Đất đai 2024' },
{ q: 'Khách hỏi: "Lô đất vườn này chắc chắn lên thổ cư được chứ em?" Câu trả lời phù hợp nhất?', options: ['Chắc chắn được, khu này ai cũng lên rồi', 'Chắc chắn được nếu anh/chị chịu chi', 'Việc chuyển mục đích phải phù hợp quy hoạch và được cấp xã cho phép; em sẽ tra quy hoạch thửa đất và gửi anh/chị trước khi cọc', 'Không bao giờ được'], answer: 2, why: 'Chuyển mục đích là thủ tục xin phép, căn cứ quy hoạch sử dụng đất; sale chỉ cung cấp thông tin đã tra cứu, không hứa kết quả thay cơ quan nhà nước.', ref: 'Điều 121 Luật Đất đai 2024' },
],
},
{
id: 'pl14', group: 'phaply', level: 3, minutes: 9,
title: 'Rủi ro pháp lý thường gặp: vi bằng, giấy tay, đất chưa sổ và tranh chấp',
intro: 'Nhà "vi bằng", đất "giấy tay" giá rẻ luôn thu hút khách. Sale chuyên nghiệp phải giải thích được vì sao chúng rủi ro và tranh chấp đất đai được giải quyết theo đường nào.',
sections: [
{ h: 'Vi bằng không thay công chứng', p: 'Từ 01/07/2026, Thừa phát lại đổi tên thành Thừa hành viên, vi bằng thực hiện theo Nghị định 151/2026/NĐ-CP (thay Nghị định 08/2020). Vi bằng chỉ ghi nhận sự kiện, hành vi có thật, là nguồn chứng cứ để tòa án xem xét; vi bằng không thay thế văn bản công chứng, chứng thực. Thừa hành viên không được lập vi bằng xác nhận nội dung hợp đồng thuộc phạm vi công chứng, hay ghi nhận việc chuyển quyền đất, tài sản không có giấy tờ. Nhà "mua bán bằng vi bằng" vì thế không sang tên được.' },
{ h: 'Giấy tay: hợp đồng chưa đúng hình thức', p: 'Hợp đồng chuyển nhượng quyền sử dụng đất giữa cá nhân phải công chứng hoặc chứng thực. Giấy viết tay không công chứng thì không đăng ký biến động được, người mua chỉ có giấy tờ để chứng minh đã trả tiền khi tranh chấp. Một số giao dịch giấy tay cũ có thể được xem xét cấp sổ theo quy định chuyển tiếp, nhưng thủ tục dài và phụ thuộc hồ sơ từng thửa; sale không nên hứa "sẽ làm sổ được".' },
{ h: 'Đất chưa có sổ: có giấy tờ hay không có giấy tờ', p: 'Đất chưa có Giấy chứng nhận thì chưa đủ điều kiện chuyển nhượng. Muốn biết khả năng cấp sổ, xem thửa đất thuộc nhóm nào: có giấy tờ về quyền sử dụng đất (giấy tờ trước 15/10/1993, sổ địa chính, giấy tờ đăng ký theo Chỉ thị 299…), hay không có giấy tờ nhưng sử dụng ổn định, không vi phạm, không tranh chấp, phù hợp quy hoạch. Mốc thời gian sử dụng đất ảnh hưởng đến việc có được cấp sổ và có phải nộp tiền sử dụng đất hay không.' },
{ h: 'Tranh chấp: hòa giải ở xã trước, rồi tòa án', p: 'Theo Luật Đất đai, trước khi cơ quan nhà nước có thẩm quyền giải quyết, các bên tranh chấp đất đai (ví dụ ai có quyền sử dụng, ranh giới thửa) phải hòa giải tại UBND cấp xã nơi có đất; thời hạn hòa giải không quá 30 ngày từ khi nhận đơn. Với tranh chấp về hợp đồng, thừa kế liên quan đến đất, việc có phải hòa giải ở xã trước khi khởi kiện hay không còn có hướng dẫn khác nhau, nên hỏi luật sư. Nếu một bên có Giấy chứng nhận hoặc giấy tờ về quyền sử dụng đất, tranh chấp do Tòa án giải quyết; nếu không bên nào có giấy tờ, các bên chọn UBND cấp có thẩm quyền hoặc khởi kiện tại tòa. Đất đang tranh chấp thì không chuyển nhượng được.' },
],
exercise: 'Soạn một đoạn giải thích 5 câu cho khách đang cân nhắc mua căn nhà "vi bằng" giá rẻ ở vùng ven: vi bằng là gì, vì sao không sang tên được, rủi ro khi người bán bán cho nhiều người, và phương án thay thế an toàn hơn trong cùng tầm tiền.',
takeaways: [
'Vi bằng không thay thế công chứng; không lập vi bằng để chuyển quyền đất không có giấy tờ.',
'Chuyển nhượng giữa cá nhân phải công chứng hoặc chứng thực; giấy tay không sang tên được.',
'Đất chưa có sổ thì chưa đủ điều kiện chuyển nhượng.',
'Tranh chấp đất phải hòa giải tại UBND cấp xã trước (tối đa 30 ngày).',
],
refs: [
{ t: 'Nghị định 151/2026/NĐ-CP, Điều 27, Điều 28 – Giá trị pháp lý của vi bằng, trường hợp không được lập vi bằng' },
{ t: 'Luật Đất đai 2024 (số 31/2024/QH15), Điều 27 khoản 3, Điều 45 khoản 1 – Công chứng và điều kiện chuyển nhượng' },
{ t: 'Luật Đất đai 2024 (số 31/2024/QH15), Điều 137, Điều 138 – Cấp Giấy chứng nhận khi có hoặc không có giấy tờ' },
{ t: 'Luật Đất đai 2024 (số 31/2024/QH15), Điều 235, Điều 236 – Hòa giải và thẩm quyền giải quyết tranh chấp' },
],
quiz: [
{ q: 'Khách hỏi: "Mua nhà bằng vi bằng có thay được công chứng không?" Câu trả lời đúng?', options: ['Được, vi bằng có giá trị như công chứng', 'Không; vi bằng chỉ ghi nhận sự kiện, hành vi có thật, không thay thế văn bản công chứng, chứng thực', 'Được nếu Thừa hành viên ký', 'Được nếu nhà dưới 1 tỷ'], answer: 1, why: 'Vi bằng là nguồn chứng cứ để tòa án xem xét và là một căn cứ cho giao dịch hợp pháp khác, nhưng không thay thế văn bản công chứng, chứng thực.', ref: 'Điều 27 khoản 3 Nghị định 151/2026/NĐ-CP' },
{ q: 'Thừa hành viên có được lập vi bằng ghi nhận việc mua bán một mảnh đất không có giấy tờ chứng minh quyền sử dụng không?', options: ['Được, nếu hai bên tự nguyện', 'Được, nếu có hàng xóm làm chứng', 'Không được, đây là trường hợp bị cấm lập vi bằng', 'Được, nếu nộp phí cao hơn'], answer: 2, why: 'Không được lập vi bằng ghi nhận sự kiện, hành vi để chuyển quyền sử dụng, quyền sở hữu đất đai, tài sản không có giấy tờ chứng minh quyền theo quy định.', ref: 'Điều 28 khoản 5 Nghị định 151/2026/NĐ-CP' },
{ q: 'Hai cá nhân mua bán đất bằng giấy viết tay, không công chứng. Hậu quả chính?', options: ['Hợp đồng không đúng hình thức bắt buộc, không đăng ký biến động sang tên được', 'Vẫn sang tên bình thường nếu nộp thuế', 'Chỉ bị phạt hành chính, vẫn sang tên được', 'Tự động được công nhận sau 1 năm'], answer: 0, why: 'Hợp đồng chuyển nhượng quyền sử dụng đất phải được công chứng hoặc chứng thực (trừ trường hợp có bên là tổ chức kinh doanh BĐS). Thiếu hình thức này, hồ sơ sang tên không được tiếp nhận.', ref: 'Điều 27 khoản 3 điểm a Luật Đất đai 2024' },
{ q: 'Hai nhà hàng xóm tranh chấp ranh giới đất. Bước bắt buộc trước khi cơ quan có thẩm quyền giải quyết là gì?', options: ['Gửi đơn lên Thanh tra Chính phủ', 'Khởi kiện thẳng ra tòa án nhân dân tối cao', 'Lập vi bằng hiện trạng', 'Hòa giải tại UBND cấp xã nơi có đất'], answer: 3, why: 'Trước khi cơ quan có thẩm quyền giải quyết tranh chấp, các bên phải hòa giải tại UBND cấp xã nơi có đất; thời hạn không quá 30 ngày kể từ ngày nhận đơn.', ref: 'Điều 235 khoản 2 Luật Đất đai 2024' },
{ q: 'Tranh chấp đất mà một bên đã có Giấy chứng nhận, hòa giải ở xã không thành. Cơ quan nào giải quyết?', options: ['Chủ tịch UBND cấp tỉnh', 'Tòa án', 'Văn phòng đăng ký đất đai', 'Sở Xây dựng'], answer: 1, why: 'Tranh chấp mà các bên hoặc một bên có Giấy chứng nhận hoặc giấy tờ quy định tại Điều 137 do Tòa án giải quyết.', ref: 'Điều 236 khoản 1 Luật Đất đai 2024' },
{ q: 'Chủ đất có giấy tờ mua bán lập trước 15/10/1993, nay được UBND cấp xã xác nhận đã sử dụng từ trước mốc đó, chưa có sổ. Nhận định nào đúng?', options: ['Thuộc nhóm có giấy tờ về quyền sử dụng đất, có cơ sở xét cấp Giấy chứng nhận; nhưng hiện chưa có sổ nên chưa đủ điều kiện chuyển nhượng', 'Đất này không bao giờ được cấp sổ', 'Được bán ngay bằng giấy tay vì đất đã cũ', 'Chỉ có thể lập vi bằng để bán'], answer: 0, why: 'Giấy tờ chuyển nhượng được UBND cấp xã xác nhận đã sử dụng trước 15/10/1993 thuộc nhóm giấy tờ về quyền sử dụng đất. Tuy vậy, muốn chuyển nhượng vẫn phải có Giấy chứng nhận trước.', ref: 'Điều 137 khoản 1, Điều 45 khoản 1 Luật Đất đai 2024' },
],
},
];
